import subprocess, time, uuid, shlex, os, json

def tmux(*args):
    return subprocess.run(["tmux"]+list(args), capture_output=True, text=True)

class PE:
    def __init__(self, input_data=None, input_file="/tmp/in.txt", args=None, cfg=None, cfgname="/tmp/cfg.json", width=80, height=24, env=None, use_file=False, wait=0.6):
        self.name="peco_"+uuid.uuid4().hex[:8]
        self.width=width; self.height=height
        if input_data is not None:
            mode='wb' if isinstance(input_data, bytes) else 'w'
            with open(input_file, mode) as f: f.write(input_data)
        self.input_file=input_file
        cmd_args=[]
        if cfg is not None:
            content=cfg if isinstance(cfg,(str,bytes)) else json.dumps(cfg)
            mode='wb' if isinstance(content,bytes) else 'w'
            with open(cfgname, mode) as f: f.write(content)
            cmd_args+=["--rcfile", cfgname]
        if args: cmd_args+=args
        self.out="/tmp/out_"+self.name+".txt"; self.err="/tmp/err_"+self.name+".txt"
        # Build shell command: HOME set to empty to avoid config if no rcfile? Use env in tmux session? We'll prefix command with env assignments
        envprefix="HOME=/tmp/emptyhome XDG_CONFIG_HOME= XDG_CONFIG_DIRS= "
        if env:
            for k,v in env.items(): envprefix+=f"{k}={shlex.quote(str(v))} "
        argstr=" ".join(shlex.quote(str(a)) for a in cmd_args)
        if use_file:
            pecocmd=f"{envprefix} ./executable {argstr} {shlex.quote(input_file)}"
        else:
            pecocmd=f"cat {shlex.quote(input_file)} | {envprefix} ./executable {argstr}"
        full=f"{pecocmd} > {self.out} 2> {self.err}; echo DONE:$?; echo --OUT--; cat -A {self.out}; echo --ERR--; cat -A {self.err}"
        tmux("new-session","-d","-s",self.name,"-x",str(width),"-y",str(height))
        time.sleep(0.15)
        tmux("send-keys","-t",self.name, full, "Enter")
        time.sleep(wait)
    def cap(self, esc=False):
        a=["capture-pane","-t",self.name,"-p"]
        if esc: a.append("-e")
        return tmux(*a).stdout
    def lines(self):
        return self.cap().split("\n")
    def show(self,label="", esc=False, trim=True):
        c=self.cap(esc=esc).split("\n")
        print(f"=== {label} ===")
        for i,l in enumerate(c):
            if trim and l=="" and i>10: continue
            print(i, repr(l))
    def esc_lines(self): return self.cap(esc=True).split("\n")
    def key(self,*keys,wait=0.45):
        tmux("send-keys","-t",self.name,*keys); time.sleep(wait)
    def lit(self,text,wait=0.45):
        tmux("send-keys","-t",self.name,"-l",text); time.sleep(wait)
    def done(self, wait=0.5):
        time.sleep(wait)
        c=self.cap()
        print(c)
        # also read files directly
        try: print("OUTFILE", repr(open(self.out,'rb').read()))
        except Exception as e: print(e)
        try: print("ERRFILE", repr(open(self.err,'rb').read()))
        except Exception as e: print(e)
        return c
    def kill(self): tmux("kill-session","-t",self.name)
    __enter__=lambda s:s
    def __exit__(self,*a): self.kill()
PY
