import sys; sys.path.insert(0,'/tmp')
from pe import PE
def getSel(s):
    for i,l in enumerate(s.esc_lines()):
        if "[4m" in l and "QUERY" not in l:
            # clean crude
            return (i, s.lines()[i])
    return None
def run(layout, keys):
    data="\n".join(f"line{i:02d}" for i in range(10))+"\n"
    with PE(data,args=["--layout",layout],height=10) as s: # perpage 8
        print("==",layout,"init",getSel(s),s.lines()[0 if layout=='top-down' else 8])
        for k in keys:
            s.key(k,wait=0.55); print(" ",k,"->",getSel(s), "promptrow",s.lines()[0 if layout=='top-down' else 8])
