from pe import PE
def filtered(data, query, filt="IgnoreCase", cfg=None):
    args=["--query",query]
    if filt!="IgnoreCase": args+=["--initial-filter",filt]
    with PE(data,args=args,cfg=cfg,height=20,wait=0.55) as s:
