package config

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"

	"github.com/gdamore/tcell/v2"
)

// OnCancelBehavior is the value of the OnCancel configuration setting.
type OnCancelBehavior string

const (
	OnCancelSuccess OnCancelBehavior = "success"
	OnCancelError   OnCancelBehavior = "error"
)

func (o *OnCancelBehavior) UnmarshalText(text []byte) error {
	s := string(text)
	switch s {
	case "", string(OnCancelSuccess), string(OnCancelError):
		*o = OnCancelBehavior(s)
		return nil
	default:
		return fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"", s)
	}
}

// Set validates and assigns the given value.
func (o *OnCancelBehavior) Set(s string) error {
	return o.UnmarshalText([]byte(s))
}

// Style is a single named style in a StyleSet. It wraps a tcell.Style.
type Style struct {
	TCell tcell.Style
}

func parseColorToken(s string) (tcell.Color, bool) {
	switch s {
	case "default":
		return tcell.ColorDefault, true
	case "black":
		return tcell.ColorBlack, true
	case "red":
		return tcell.ColorRed, true
	case "green":
		return tcell.ColorGreen, true
	case "yellow":
		return tcell.ColorYellow, true
	case "blue":
		return tcell.ColorBlue, true
	case "magenta":
		return tcell.ColorMagenta, true
	case "cyan":
		return tcell.ColorCyan, true
	case "white":
		return tcell.ColorWhite, true
	}
	if len(s) == 7 && s[0] == '#' {
		v, err := strconv.ParseInt(s[1:], 16, 32)
		if err != nil {
			return tcell.ColorDefault, false
		}
		return tcell.NewHexColor(int32(v)), true
	}
	if s != "" {
		isDigit := true
		for _, r := range s {
			if r < '0' || r > '9' {
				isDigit = false
				break
			}
		}
		if isDigit {
			n, err := strconv.Atoi(s)
			if err == nil && n >= 0 && n <= 255 {
				return tcell.PaletteColor(n), true
			}
		}
	}
	return tcell.ColorDefault, false
}

// ParseStyleTokens builds a Style from a list of style tokens.
func ParseStyleTokens(tokens []string) Style {
	st := tcell.StyleDefault
	for _, tok := range tokens {
		switch tok {
		case "bold", "on_bold":
			st = st.Bold(true)
			continue
		case "underline":
			st = st.Underline(true)
			continue
		case "reverse":
			st = st.Reverse(true)
			continue
		}
		if strings.HasPrefix(tok, "on_") {
			if c, ok := parseColorToken(tok[3:]); ok {
				st = st.Background(c)
			}
			continue
		}
		if c, ok := parseColorToken(tok); ok {
			st = st.Foreground(c)
		}
	}
	return Style{TCell: st}
}

func (s *Style) UnmarshalJSON(data []byte) error {
	var tokens []string
	if err := json.Unmarshal(data, &tokens); err != nil {
		return fmt.Errorf("failed to unmarshal Style: %w", err)
	}
	*s = ParseStyleTokens(tokens)
	return nil
}

// StyleSet is the set of configurable styles.
type StyleSet struct {
	Basic          Style `yaml:"Basic"`
	SavedSelection Style `yaml:"SavedSelection"`
	Selected       Style `yaml:"Selected"`
	Query          Style `yaml:"Query"`
	QueryCursor    Style `yaml:"QueryCursor"`
	Matched        Style `yaml:"Matched"`
	Prompt         Style `yaml:"Prompt"`
	Context        Style `yaml:"Context"`
}

// DefaultStyleSet returns the built-in styles.
func DefaultStyleSet() StyleSet {
	return StyleSet{
		Basic:          Style{TCell: tcell.StyleDefault},
		SavedSelection: Style{TCell: tcell.StyleDefault.Foreground(tcell.ColorBlack).Background(tcell.ColorCyan).Bold(true)},
		Selected:       Style{TCell: tcell.StyleDefault.Background(tcell.ColorMagenta).Underline(true)},
		Query:          Style{TCell: tcell.StyleDefault},
		QueryCursor:    Style{TCell: tcell.StyleDefault},
		Matched:        Style{TCell: tcell.StyleDefault.Foreground(tcell.ColorCyan)},
		Prompt:         Style{TCell: tcell.StyleDefault},
		Context:        Style{TCell: tcell.StyleDefault.Bold(true)},
	}
}

// SingleKeyJumpConfig holds SingleKeyJump settings.
type SingleKeyJumpConfig struct {
	ShowPrefix bool `yaml:"ShowPrefix"`
}

// CustomFilterConfig describes an external filter command.
type CustomFilterConfig struct {
	Cmd             string   `yaml:"Cmd"`
	Args            []string `yaml:"Args"`
	BufferThreshold int      `yaml:"BufferThreshold"`
}

// Config is the root of the configuration file.
