		{long: "ansi", display: "--ansi", isBool: true, setBool: func(o *cliOptions) { o.ANSI = true }},
		{long: "height", display: "--height", set: func(o *cliOptions, v string) error { o.Height = v; return nil }},
	}
}

func isLongArg(s string) bool {
	return len(s) >= 3 && s[0] == '-' && s[1] == '-' && s[2] != '-'
}
func isShortArg(s string) bool {
	return len(s) >= 2 && s[0] == '-' && s[1] != '-'
}

func looksLikeOption(s string, forInt bool) bool {
	if isLongArg(s) {
		return true
	}
	if isShortArg(s) {
		if forInt {
			// Allow negative numbers as values for int flags.
			if len(s) >= 2 && s[1] >= '0' && s[1] <= '9' {
				return false
			}
		}
		return true
	}
	return false
}

// parseCLI parses arguments. On a parse error it prints the error and usage
// to errOut, and returns an error whose message is errMsg. The caller wraps it.
func parseCLI(args []string, errOut io.Writer) (*cliOptions, string, error) {
	opts := &cliOptions{}
	defs := flagDefs()
	byLong := map[string]*flagDef{}
	byShort := map[rune]*flagDef{}
	for i := range defs {
		d := &defs[i]
		byLong[d.long] = d
		if d.short != 0 {
			byShort[d.short] = d
		}
	}
	fail := func(msg string) (*cliOptions, string, error) {
		fmt.Fprintf(errOut, "%s\n", msg)
		fmt.Fprint(errOut, usageText)
		return nil, msg, fmt.Errorf("%s", msg)
	}
	setValue := func(d *flagDef, v string) string {
		if err := d.set(opts, v); err != nil {
			if d.isInt {
				return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", d.display, err.Error())
			}
			return err.Error()
		}
		return ""
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case isLongArg(arg):
			body := arg[2:]
			name := body
			val := ""
			hasEq := false
			if idx := strings.IndexByte(body, '='); idx >= 0 {
				name = body[:idx]
				val = body[idx+1:]
				hasEq = true
			}
			d, ok := byLong[name]
			if !ok {
				return fail(fmt.Sprintf("unknown flag `%s'", name))
			}
			if d.isBool {
				if hasEq {
					return fail(fmt.Sprintf("bool flag `%s' cannot have an argument", d.display))
				}
				d.setBool(opts)
				continue
			}
			if hasEq {
				if msg := setValue(d, val); msg != "" {
					return fail(msg)
				}
				continue
			}
			if i+1 >= len(args) {
				return fail(fmt.Sprintf("expected argument for flag `%s'", d.display))
			}
			next := args[i+1]
			if looksLikeOption(next, d.isInt) {
				return fail(fmt.Sprintf("expected argument for flag `%s', but got option `%s'", d.display, next))
			}
			i++
			if msg := setValue(d, next); msg != "" {
				return fail(msg)
			}
		case isShortArg(arg):
			runes := []rune(arg[1:])
			consumedNext := false
			for idx, r := range runes {
				d, ok := byShort[r]
				if !ok {
					return fail(fmt.Sprintf("unknown flag `%c'", r))
				}
				rest := string(runes[idx+1:])
				if d.isBool {
					if strings.HasPrefix(rest, "=") {
						return fail(fmt.Sprintf("bool flag `%s' cannot have an argument", d.display))
					}
					d.setBool(opts)
					continue
				}
				// value flag
				if rest != "" {
					v := rest
					if strings.HasPrefix(v, "=") {
						v = v[1:]
					}
					if msg := setValue(d, v); msg != "" {
						return fail(msg)
					}
				} else {
					if i+1 >= len(args) {
						return fail(fmt.Sprintf("expected argument for flag `%s'", d.display))
					}
					next := args[i+1]
					if looksLikeOption(next, d.isInt) {
						return fail(fmt.Sprintf("expected argument for flag `%s', but got option `%s'", d.display, next))
					}
					if msg := setValue(d, next); msg != "" {
						return fail(msg)
					}
					consumedNext = true
				}
				break
			}
			if consumedNext {
				i++
			}
		default:
			opts.Args = append(opts.Args, arg)
		}
	}
	return opts, "", nil
}

func validLayout(s string) bool {
	switch s {
	case "top-down", "bottom-up", "top-down-query-bottom":
		return true
	}
	return false
}
EOF
gofmt -w cli.go"}

{"command":"cat > configload.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"pecoreimpl/config"

	"gopkg.in/yaml.v3"
)

func isYAMLPath(path string) bool {
	return strings.HasSuffix(path, ".yaml") || strings.HasSuffix(path, ".yml")
}

func readConfigFile(path string) (*config.Config, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("failed to open file %s: %w", path, err)
	}
	defer f.Close()
	cfg := config.New()
	if isYAMLPath(path) {
		data, err := io.ReadAll(f)
		if err != nil {
			return nil, fmt.Errorf("failed to decode YAML: %w", err)
		}
		if err := decodeYAMLConfig(data, cfg); err != nil {
			// Layout errors are reported without the decode wrapper; they are
			// validated below. decodeYAMLConfig returns decode errors already
			// describing the problem.
			return nil, err
		}
	} else {
		dec := json.NewDecoder(f)
		if err := dec.Decode(cfg); err != nil {
			return nil, fmt.Errorf("failed to decode JSON: %w", err)
		}
	}
	if !validLayout(cfg.Layout) {
		return nil, fmt.Errorf("invalid layout type: %s", cfg.Layout)
	}
	return cfg, nil
}

func configSearchPaths() []string {
	var dirs []string
	home, _ := os.UserHomeDir()
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		dirs = append(dirs, filepath.Join(x, "peco"))
	} else if home != "" {
		dirs = append(dirs, filepath.Join(home, ".config", "peco"))
	}
	if v, ok := os.LookupEnv("XDG_CONFIG_DIRS"); ok && v != "" {
		for _, d := range strings.Split(v, ":") {
			dirs = append(dirs, filepath.Join(d, "peco"))
		}
	}
	if home != "" {
		dirs = append(dirs, filepath.Join(home, ".peco"))
	}
	var paths []string
	for _, d := range dirs {
		for _, name := range []string{"config.json", "config.yaml", "config.yml"} {
			paths = append(paths, filepath.Join(d, name))
		}
	}
	return paths
}

func loadConfig(rcfile string) (*config.Config, error) {
	if rcfile != "" {
		cfg, err := readConfigFile(rcfile)
		if err != nil {
			return nil, fmt.Errorf("failed to read config file: %w", err)
		}
		return cfg, nil
	}
	for _, path := range configSearchPaths() {
		if _, err := os.Stat(path); err != nil {
			continue
		}
		cfg, err := readConfigFile(path)
		if err != nil {
			return nil, fmt.Errorf("failed to read config file: %w", err)
		}
		return cfg, nil
	}
	return config.New(), nil
}

// ---- YAML decoding (manual, to mimic loose scalar conversion) ----

type yamlDecodeError struct{ msg string }

func (e *yamlDecodeError) Error() string { return e.msg }

func yamlKindName(n *yaml.Node) string {
	switch n.Kind {
	case yaml.SequenceNode:
		return "sequence"
	case yaml.MappingNode:
		return "mapping"
	case yaml.DocumentNode:
		return "document"
	}
	switch n.Tag {
	case "!!int":
		return "int"
	case "!!str":
		return "string"
	case "!!bool":
		return "bool"
	case "!!null":
		return "null"
	case "!!float":
		return "float"
	}
	return "string"
}

func yamlAnnotate(data []byte, line, col int, msg string) error {
	lines := strings.Split(string(data), "\n")
	var b strings.Builder
	fmt.Fprintf(&b, "failed to decode YAML: [%d:%d] %s\n", line, col, msg)
	start := line - 2
	if start < 1 {
		start = 1
	}
	for ln := start; ln <= line && ln <= len(lines); ln++ {
		prefix := "   "
		if ln == line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, ln, strings.ReplaceAll(lines[ln-1], "\t", " "))
		if ln == line {
			caret := strings.Repeat(" ", len(strconv.Itoa(ln))+3+col)
			// prefix is ">  N | " : 3 + len(N) + 3 characters before content
			caret = strings.Repeat(" ", col+len(strconv.Itoa(ln))+5)
			fmt.Fprintf(&b, "%s^\n", caret)
		}
	}
	b.WriteString("\n")
	// remove one trailing newline: Error() value ends with single \n, caller adds another
	s := b.String()
	s = strings.TrimSuffix(s, "\n")
	return &yamlDecodeError{msg: s}
}

func yamlTypeError(data []byte, n *yaml.Node, msg string) error {
	return yamlAnnotate(data, n.Line, n.Column, msg)
}

func decodeYAMLConfig(data []byte, cfg *config.Config) error {
	dec := yaml.NewDecoder(strings.NewReader(string(data)))
	var doc yaml.Node
	if err := dec.Decode(&doc); err != nil {
		if err == io.EOF {
			return fmt.Errorf("failed to decode YAML: EOF")
		}
		return fmt.Errorf("failed to decode YAML: %w", err)
	}
	if len(doc.Content) == 0 {
		return fmt.Errorf("failed to decode YAML: EOF")
	}
	root := doc.Content[0]
	// duplicate key check on root mapping (goccy-like)
	if err := yamlCheckDuplicates(data, root); err != nil {
		return err
	}
	if root.Kind != yaml.MappingNode {
		return yamlTypeError(data, root, fmt.Sprintf("%s was used where mapping is expected", yamlKindName(root)))
	}
	// Walk pairs
	for i := 0; i+1 < len(root.Content); i += 2 {
		keyNode := root.Content[i]
		valNode := root.Content[i+1]
		key := keyNode.Value
		if err := yamlApplyField(data, cfg, key, valNode); err != nil {
			return err
		}
	}
	return nil
}

func yamlCheckDuplicates(data []byte, n *yaml.Node) error {
	if n.Kind == yaml.DocumentNode && len(n.Content) > 0 {
		return yamlCheckDuplicates(data, n.Content[0])
	}
	if n.Kind == yaml.MappingNode {
		seen := map[string]*yaml.Node{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := n.Content[i]
			if prev, ok := seen[k.Value]; ok {
				return yamlAnnotate(data, k.Line, k.Column, fmt.Sprintf("mapping key %q already defined at [%d:%d]", k.Value, prev.Line, prev.Column))
			}
			seen[k.Value] = k
			if err := yamlCheckDuplicates(data, n.Content[i+1]); err != nil {
				return err
			}
		}
	}
	if n.Kind == yaml.SequenceNode {
		for _, c := range n.Content {
			if err := yamlCheckDuplicates(data, c); err != nil {
				return err
			}
		}
	}
	return nil
}

func nodeIsNull(n *yaml.Node) bool {
	return n.Tag == "!!null"
}

func yamlStringValue(data []byte, n *yaml.Node, fieldPath string) (string, bool, error) {
	if nodeIsNull(n) {
		return "", false, nil
	}
	if n.Kind != yaml.ScalarNode {
		return "", false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type string", yamlTypeDesc(n), fieldPath))
	}
	// Loose conversion: ints and bools are formatted.
	switch n.Tag {
	case "!!int":
		var iv int64
		if err := n.Decode(&iv); err == nil {
			return strconv.FormatInt(iv, 10), true, nil
		}
		return n.Value, true, nil
	case "!!bool":
		var bv bool
		if err := n.Decode(&bv); err == nil {
			if bv {
				return "true", true, nil
			}
			return "false", true, nil
		}
		return n.Value, true, nil
	case "!!float":
		return n.Value, true, nil
	default:
		return n.Value, true, nil
	}
}

func yamlTypeDesc(n *yaml.Node) string {
	switch n.Kind {
	case yaml.SequenceNode:
		return "[]interface {}"
	case yaml.MappingNode:
		return "map[string]interface {}"
	}
	switch n.Tag {
	case "!!int":
		return "int"
	case "!!bool":
		return "bool"
	case "!!float":
		return "float64"
	case "!!null":
		return "null"
	}
	return "string"
}

func yamlBoolValue(data []byte, n *yaml.Node, fieldPath string) (bool, bool, error) {
	if nodeIsNull(n) {
		return false, false, nil
	}
	if n.Kind == yaml.ScalarNode {
		switch strings.ToLower(n.Value) {
		case "true":
			if n.Value == "true" || n.Value == "True" || n.Value == "TRUE" {
				return true, true, nil
			}
		case "false":
			if n.Value == "false" || n.Value == "False" || n.Value == "FALSE" {
				return false, true, nil
			}
		}
		if n.Tag == "!!bool" {
			var bv bool
			if err := n.Decode(&bv); err == nil {
				return bv, true, nil
			}
		}
	}
	return false, false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type bool", yamlScalarKindForError(n), fieldPath))
}

func yamlScalarKindForError(n *yaml.Node) string {
	if n.Kind == yaml.SequenceNode {
		return "[]interface {}"
	}
	if n.Kind == yaml.MappingNode {
		return "map[string]interface {}"
	}
	if n.Tag == "!!int" {
		return "int"
	}
	return "string"
}

func yamlIntValue(data []byte, n *yaml.Node, fieldPath string) (int, bool, error) {
	if nodeIsNull(n) {
		return 0, false, nil
	}
	if n.Kind == yaml.ScalarNode && n.Tag == "!!int" {
		var iv int
		if err := n.Decode(&iv); err == nil {
			return iv, true, nil
		}
	}
	return 0, false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type int", yamlScalarKindForError(n), fieldPath))
}

func yamlStringSlice(data []byte, n *yaml.Node, styleErr bool) ([]string, error) {
	if nodeIsNull(n) {
		return nil, nil
	}
	if n.Kind != yaml.SequenceNode {
		if styleErr {
			return nil, &yamlDecodeError{msg: "failed to decode YAML: " + styleYAMLInner(data, n)}
		}
		return nil, yamlTypeError(data, n, fmt.Sprintf("%s was used where sequence is expected", yamlKindName(n)))
	}
	out := []string{}
	for _, c := range n.Content {
		s, _, err := yamlStringValue(data, c, "[]string")
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func styleYAMLInner(data []byte, n *yaml.Node) string {
	msg := fmt.Sprintf("failed to unmarshal Style from YAML: [%d:%d] %s was used where sequence is expected", n.Line, n.Column, yamlKindName(n))
	lines := strings.Split(string(data), "\n")
	var b strings.Builder
	b.WriteString(msg + "\n")
	start := n.Line - 1
	if start < 1 {
		start = 1
	}
	for ln := start; ln <= n.Line && ln <= len(lines); ln++ {
		prefix := "   "
		if ln == n.Line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, ln, lines[ln-1])
		if ln == n.Line {
			fmt.Fprintf(&b, "%s^\n", strings.Repeat(" ", n.Column+len(strconv.Itoa(ln))+5))
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

func mappingPairs(data []byte, n *yaml.Node, fieldPath string) ([][2]*yaml.Node, error) {
	if nodeIsNull(n) {
		return nil, nil
	}
	if n.Kind != yaml.MappingNode {
		return nil, yamlTypeError(data, n, fmt.Sprintf("%s was used where mapping is expected", yamlKindName(n)))
	}
	var pairs [][2]*yaml.Node
	for i := 0; i+1 < len(n.Content); i += 2 {
		pairs = append(pairs, [2]*yaml.Node{n.Content[i], n.Content[i+1]})
	}
	return pairs, nil
}

func yamlApplyField(data []byte, cfg *config.Config, key string, val *yaml.Node) error {
	switch key {
	case "Prompt":
		s, ok, err := yamlStringValue(data, val, "Config.Prompt")
		if err == nil && ok {
			cfg.Prompt = s
		}
		return err
	case "InitialFilter":
		s, ok, err := yamlStringValue(data, val, "Config.InitialFilter")
		if err == nil && ok {
			cfg.InitialFilter = s
		}
		return err
	case "Layout":
		s, ok, err := yamlStringValue(data, val, "Config.Layout")
		if err == nil && ok {
			cfg.Layout = s
		}
		return err
	case "SelectionPrefix":
		s, ok, err := yamlStringValue(data, val, "Config.SelectionPrefix")
		if err == nil && ok {
			cfg.SelectionPrefix = s
		}
		return err
	case "Height":
		s, ok, err := yamlStringValue(data, val, "Config.Height")
		if err == nil && ok {
			cfg.Height = s
		}
		return err
	case "FuzzyLongestSort":
		b, ok, err := yamlBoolValue(data, val, "Config.FuzzyLongestSort")
		if err == nil && ok {
			cfg.FuzzyLongestSort = b
		}
		return err
	case "StickySelection":
		b, ok, err := yamlBoolValue(data, val, "Config.StickySelection")
		if err == nil && ok {
			cfg.StickySelection = b
		}
		return err
	case "SuppressStatusMsg":
		b, ok, err := yamlBoolValue(data, val, "Config.SuppressStatusMsg")
		if err == nil && ok {
			cfg.SuppressStatusMsg = b
		}
		return err
	case "ANSI":
		b, ok, err := yamlBoolValue(data, val, "Config.ANSI")
		if err == nil && ok {
			cfg.ANSI = b
		}
		return err
	case "MaxScanBufferSize":
		iv, ok, err := yamlIntValue(data, val, "Config.MaxScanBufferSize")
		if err == nil && ok {
			cfg.MaxScanBufferSize = iv
		}
		return err
	case "OnCancel":
		if nodeIsNull(val) {
			return nil
		}
		s, ok, err := yamlStringValue(data, val, "Config.OnCancel")
		if err != nil {
			return err
		}
		if ok {
			if err := cfg.OnCancel.Set(s); err != nil {
				return fmt.Errorf("failed to decode YAML: %w", err)
			}
		}
		return nil
	case "Keymap":
		pairs, err := mappingPairs(data, val, "Config.Keymap")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.Keymap == nil {
				cfg.Keymap = map[string]string{}
			}
			for _, p := range pairs {
				s, _, err := yamlStringValue(data, p[1], "Config.Keymap")
				if err != nil {
					return err
				}
				cfg.Keymap[p[0].Value] = s
			}
		}
		return nil
	case "Action":
		pairs, err := mappingPairs(data, val, "Config.Action")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.Action == nil {
				cfg.Action = map[string][]string{}
			}
			for _, p := range pairs {
				ss, err := yamlStringSlice(data, p[1], false)
				if err != nil {
					return err
				}
				cfg.Action[p[0].Value] = ss
			}
		}
		return nil
	case "Style":
		pairs, err := mappingPairs(data, val, "Config.Style")
		if err != nil {
			return err
		}
		for _, p := range pairs {
			ss, err := yamlStringSlice(data, p[1], true)
			if err != nil {
				return err
			}
			st := config.ParseStyleTokens(ss)
			switch p[0].Value {
			case "Basic":
				cfg.Style.Basic = st
			case "SavedSelection":
				cfg.Style.SavedSelection = st
			case "Selected":
				cfg.Style.Selected = st
			case "Query":
				cfg.Style.Query = st
			case "QueryCursor":
				cfg.Style.QueryCursor = st
			case "Matched":
				cfg.Style.Matched = st
			case "Prompt":
				cfg.Style.Prompt = st
			case "Context":
				cfg.Style.Context = st
			}
		}
		return nil
	case "CustomFilter":
		pairs, err := mappingPairs(data, val, "Config.CustomFilter")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.CustomFilter == nil {
				cfg.CustomFilter = map[string]config.CustomFilterConfig{}
			}
			for _, p := range pairs {
				var cf config.CustomFilterConfig
				sub, err := mappingPairs(data, p[1], "Config.CustomFilter")
				if err != nil {
					return err
				}
				for _, sp := range sub {
					switch sp[0].Value {
					case "Cmd":
						s, _, err := yamlStringValue(data, sp[1], "CustomFilterConfig.CustomFilter.Cmd")
						if err != nil {
							return err
						}
						cf.Cmd = s
					case "Args":
						ss, err := yamlStringSlice(data, sp[1], false)
						if err != nil {
							return err
						}
						cf.Args = ss
					case "BufferThreshold":
						iv, _, err := yamlIntValue(data, sp[1], "CustomFilterConfig.CustomFilter.BufferThreshold")
						if err != nil {
							return err
						}
						cf.BufferThreshold = iv
					}
				}
				cfg.CustomFilter[p[0].Value] = cf
			}
		}
		return nil
	case "SingleKeyJump":
		pairs, err := mappingPairs(data, val, "Config.SingleKeyJump")
		if err != nil {
			return err
		}
		for _, p := range pairs {
			if p[0].Value == "ShowPrefix" {
				b, ok, err := yamlBoolValue(data, p[1], "Config.SingleKeyJump")
				if err != nil {
					return err
				}
				if ok {
					cfg.SingleKeyJump.ShowPrefix = b
				}
			}
		}
		return nil
	default:
		return nil
	}
}
