// ---- YAML decoding (manual, to mimic loose scalar conversion) ----

type yamlDecodeError struct{ msg string }

func (e *yamlDecodeError) Error() string { return e.msg }

func yamlKindName(n *yaml.Node) string {
	switch n.Kind {
	case yaml.SequenceNode:
		return "sequence"
	case yaml.MappingNode:
		return "mapping"
	case yaml.DocumentNode:
		return "document"
	}
	switch n.Tag {
	case "!!int":
		return "int"
	case "!!str":
		return "string"
	case "!!bool":
		return "bool"
	case "!!null":
		return "null"
	case "!!float":
		return "float"
	}
	return "string"
}

func yamlAnnotate(data []byte, line, col int, msg string) error {
	lines := strings.Split(string(data), "\n")
	var b strings.Builder
	fmt.Fprintf(&b, "failed to decode YAML: [%d:%d] %s\n", line, col, msg)
	start := line - 2
	if start < 1 {
		start = 1
	}
	for ln := start; ln <= line && ln <= len(lines); ln++ {
		prefix := "   "
		if ln == line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, ln, strings.ReplaceAll(lines[ln-1], "\t", " "))
		if ln == line {
			caret := strings.Repeat(" ", len(strconv.Itoa(ln))+3+col)
			// prefix is ">  N | " : 3 + len(N) + 3 characters before content
			caret = strings.Repeat(" ", col+len(strconv.Itoa(ln))+5)
			fmt.Fprintf(&b, "%s^\n", caret)
		}
	}
	b.WriteString("\n")
	// remove one trailing newline: Error() value ends with single \n, caller adds another
	s := b.String()
	s = strings.TrimSuffix(s, "\n")
	return &yamlDecodeError{msg: s}
}

func yamlTypeError(data []byte, n *yaml.Node, msg string) error {
	return yamlAnnotate(data, n.Line, n.Column, msg)
}

func decodeYAMLConfig(data []byte, cfg *config.Config) error {
	dec := yaml.NewDecoder(strings.NewReader(string(data)))
	var doc yaml.Node
	if err := dec.Decode(&doc); err != nil {
		if err == io.EOF {
			return fmt.Errorf("failed to decode YAML: EOF")
		}
		return fmt.Errorf("failed to decode YAML: %w", err)
	}
	if len(doc.Content) == 0 {
		return fmt.Errorf("failed to decode YAML: EOF")
	}
	root := doc.Content[0]
	// duplicate key check on root mapping (goccy-like)
	if err := yamlCheckDuplicates(data, root); err != nil {
		return err
	}
	if root.Kind != yaml.MappingNode {
		return yamlTypeError(data, root, fmt.Sprintf("%s was used where mapping is expected", yamlKindName(root)))
	}
	// Walk pairs
	for i := 0; i+1 < len(root.Content); i += 2 {
		keyNode := root.Content[i]
		valNode := root.Content[i+1]
		key := keyNode.Value
		if err := yamlApplyField(data, cfg, key, valNode); err != nil {
			return err
		}
	}
	return nil
}

func yamlCheckDuplicates(data []byte, n *yaml.Node) error {
	if n.Kind == yaml.DocumentNode && len(n.Content) > 0 {
		return yamlCheckDuplicates(data, n.Content[0])
	}
	if n.Kind == yaml.MappingNode {
		seen := map[string]*yaml.Node{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := n.Content[i]
			if prev, ok := seen[k.Value]; ok {
				return yamlAnnotate(data, k.Line, k.Column, fmt.Sprintf("mapping key %q already defined at [%d:%d]", k.Value, prev.Line, prev.Column))
			}
			seen[k.Value] = k
			if err := yamlCheckDuplicates(data, n.Content[i+1]); err != nil {
				return err
			}
		}
	}
	if n.Kind == yaml.SequenceNode {
		for _, c := range n.Content {
			if err := yamlCheckDuplicates(data, c); err != nil {
				return err
			}
		}
	}
	return nil
}

func nodeIsNull(n *yaml.Node) bool {
	return n.Tag == "!!null"
}

func yamlStringValue(data []byte, n *yaml.Node, fieldPath string) (string, bool, error) {
	if nodeIsNull(n) {
		return "", false, nil
	}
	if n.Kind != yaml.ScalarNode {
		return "", false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type string", yamlTypeDesc(n), fieldPath))
	}
	// Loose conversion: ints and bools are formatted.
	switch n.Tag {
	case "!!int":
		var iv int64
		if err := n.Decode(&iv); err == nil {
			return strconv.FormatInt(iv, 10), true, nil
		}
		return n.Value, true, nil
	case "!!bool":
		var bv bool
		if err := n.Decode(&bv); err == nil {
			if bv {
				return "true", true, nil
			}
			return "false", true, nil
		}
		return n.Value, true, nil
	case "!!float":
		return n.Value, true, nil
	default:
		return n.Value, true, nil
	}
}

func yamlTypeDesc(n *yaml.Node) string {
	switch n.Kind {
	case yaml.SequenceNode:
		return "[]interface {}"
	case yaml.MappingNode:
		return "map[string]interface {}"
	}
	switch n.Tag {
	case "!!int":
		return "int"
	case "!!bool":
		return "bool"
	case "!!float":
		return "float64"
	case "!!null":
		return "null"
	}
	return "string"
}

func yamlBoolValue(data []byte, n *yaml.Node, fieldPath string) (bool, bool, error) {
	if nodeIsNull(n) {
		return false, false, nil
	}
	if n.Kind == yaml.ScalarNode {
		switch strings.ToLower(n.Value) {
		case "true":
			if n.Value == "true" || n.Value == "True" || n.Value == "TRUE" {
				return true, true, nil
			}
		case "false":
			if n.Value == "false" || n.Value == "False" || n.Value == "FALSE" {
				return false, true, nil
			}
		}
		if n.Tag == "!!bool" {
			var bv bool
			if err := n.Decode(&bv); err == nil {
				return bv, true, nil
			}
		}
	}
	return false, false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type bool", yamlScalarKindForError(n), fieldPath))
}

func yamlScalarKindForError(n *yaml.Node) string {
	if n.Kind == yaml.SequenceNode {
		return "[]interface {}"
	}
	if n.Kind == yaml.MappingNode {
		return "map[string]interface {}"
	}
	if n.Tag == "!!int" {
		return "int"
	}
	return "string"
}

func yamlIntValue(data []byte, n *yaml.Node, fieldPath string) (int, bool, error) {
	if nodeIsNull(n) {
		return 0, false, nil
	}
	if n.Kind == yaml.ScalarNode && n.Tag == "!!int" {
		var iv int
		if err := n.Decode(&iv); err == nil {
			return iv, true, nil
		}
	}
	return 0, false, yamlTypeError(data, n, fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type int", yamlScalarKindForError(n), fieldPath))
}

func yamlStringSlice(data []byte, n *yaml.Node, styleErr bool) ([]string, error) {
	if nodeIsNull(n) {
		return nil, nil
	}
	if n.Kind != yaml.SequenceNode {
		if styleErr {
			return nil, &yamlDecodeError{msg: "failed to decode YAML: " + styleYAMLInner(data, n)}
		}
		return nil, yamlTypeError(data, n, fmt.Sprintf("%s was used where sequence is expected", yamlKindName(n)))
	}
	out := []string{}
	for _, c := range n.Content {
		s, _, err := yamlStringValue(data, c, "[]string")
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func styleYAMLInner(data []byte, n *yaml.Node) string {
	msg := fmt.Sprintf("failed to unmarshal Style from YAML: [%d:%d] %s was used where sequence is expected", n.Line, n.Column, yamlKindName(n))
	lines := strings.Split(string(data), "\n")
	var b strings.Builder
	b.WriteString(msg + "\n")
	start := n.Line - 1
	if start < 1 {
		start = 1
	}
	for ln := start; ln <= n.Line && ln <= len(lines); ln++ {
		prefix := "   "
		if ln == n.Line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, ln, lines[ln-1])
		if ln == n.Line {
			fmt.Fprintf(&b, "%s^\n", strings.Repeat(" ", n.Column+len(strconv.Itoa(ln))+5))
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

func mappingPairs(data []byte, n *yaml.Node, fieldPath string) ([][2]*yaml.Node, error) {
	if nodeIsNull(n) {
		return nil, nil
	}
	if n.Kind != yaml.MappingNode {
		return nil, yamlTypeError(data, n, fmt.Sprintf("%s was used where mapping is expected", yamlKindName(n)))
	}
	var pairs [][2]*yaml.Node
	for i := 0; i+1 < len(n.Content); i += 2 {
		pairs = append(pairs, [2]*yaml.Node{n.Content[i], n.Content[i+1]})
	}
	return pairs, nil
}

func yamlApplyField(data []byte, cfg *config.Config, key string, val *yaml.Node) error {
	switch key {
	case "Prompt":
		s, ok, err := yamlStringValue(data, val, "Config.Prompt")
		if err == nil && ok {
			cfg.Prompt = s
		}
		return err
	case "InitialFilter":
		s, ok, err := yamlStringValue(data, val, "Config.InitialFilter")
		if err == nil && ok {
			cfg.InitialFilter = s
		}
		return err
	case "Layout":
		s, ok, err := yamlStringValue(data, val, "Config.Layout")
		if err == nil && ok {
			cfg.Layout = s
		}
		return err
	case "SelectionPrefix":
		s, ok, err := yamlStringValue(data, val, "Config.SelectionPrefix")
		if err == nil && ok {
			cfg.SelectionPrefix = s
		}
		return err
	case "Height":
		s, ok, err := yamlStringValue(data, val, "Config.Height")
		if err == nil && ok {
			cfg.Height = s
		}
		return err
	case "FuzzyLongestSort":
		b, ok, err := yamlBoolValue(data, val, "Config.FuzzyLongestSort")
		if err == nil && ok {
			cfg.FuzzyLongestSort = b
		}
		return err
	case "StickySelection":
		b, ok, err := yamlBoolValue(data, val, "Config.StickySelection")
		if err == nil && ok {
			cfg.StickySelection = b
		}
		return err
	case "SuppressStatusMsg":
		b, ok, err := yamlBoolValue(data, val, "Config.SuppressStatusMsg")
		if err == nil && ok {
			cfg.SuppressStatusMsg = b
		}
		return err
	case "ANSI":
		b, ok, err := yamlBoolValue(data, val, "Config.ANSI")
		if err == nil && ok {
			cfg.ANSI = b
		}
		return err
	case "MaxScanBufferSize":
		iv, ok, err := yamlIntValue(data, val, "Config.MaxScanBufferSize")
		if err == nil && ok {
			cfg.MaxScanBufferSize = iv
		}
		return err
	case "OnCancel":
		if nodeIsNull(val) {
			return nil
		}
		s, ok, err := yamlStringValue(data, val, "Config.OnCancel")
		if err != nil {
			return err
		}
		if ok {
			if err := cfg.OnCancel.Set(s); err != nil {
				return fmt.Errorf("failed to decode YAML: %w", err)
			}
		}
		return nil
	case "Keymap":
		pairs, err := mappingPairs(data, val, "Config.Keymap")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.Keymap == nil {
				cfg.Keymap = map[string]string{}
			}
			for _, p := range pairs {
				s, _, err := yamlStringValue(data, p[1], "Config.Keymap")
				if err != nil {
					return err
				}
				cfg.Keymap[p[0].Value] = s
			}
		}
		return nil
	case "Action":
		pairs, err := mappingPairs(data, val, "Config.Action")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.Action == nil {
				cfg.Action = map[string][]string{}
			}
			for _, p := range pairs {
				ss, err := yamlStringSlice(data, p[1], false)
				if err != nil {
					return err
				}
				cfg.Action[p[0].Value] = ss
			}
		}
		return nil
	case "Style":
		pairs, err := mappingPairs(data, val, "Config.Style")
		if err != nil {
			return err
		}
		for _, p := range pairs {
			ss, err := yamlStringSlice(data, p[1], true)
			if err != nil {
				return err
			}
			st := config.ParseStyleTokens(ss)
			switch p[0].Value {
			case "Basic":
				cfg.Style.Basic = st
			case "SavedSelection":
				cfg.Style.SavedSelection = st
			case "Selected":
				cfg.Style.Selected = st
			case "Query":
				cfg.Style.Query = st
			case "QueryCursor":
				cfg.Style.QueryCursor = st
			case "Matched":
				cfg.Style.Matched = st
			case "Prompt":
				cfg.Style.Prompt = st
			case "Context":
				cfg.Style.Context = st
			}
		}
		return nil
	case "CustomFilter":
		pairs, err := mappingPairs(data, val, "Config.CustomFilter")
		if err != nil {
			return err
		}
		if pairs != nil {
			if cfg.CustomFilter == nil {
				cfg.CustomFilter = map[string]config.CustomFilterConfig{}
			}
			for _, p := range pairs {
				var cf config.CustomFilterConfig
				sub, err := mappingPairs(data, p[1], "Config.CustomFilter")
				if err != nil {
					return err
				}
				for _, sp := range sub {
					switch sp[0].Value {
					case "Cmd":
						s, _, err := yamlStringValue(data, sp[1], "CustomFilterConfig.CustomFilter.Cmd")
						if err != nil {
							return err
						}
						cf.Cmd = s
					case "Args":
						ss, err := yamlStringSlice(data, sp[1], false)
						if err != nil {
							return err
						}
						cf.Args = ss
					case "BufferThreshold":
						iv, _, err := yamlIntValue(data, sp[1], "CustomFilterConfig.CustomFilter.BufferThreshold")
						if err != nil {
							return err
						}
						cf.BufferThreshold = iv
					}
				}
				cfg.CustomFilter[p[0].Value] = cf
			}
		}
		return nil
	case "SingleKeyJump":
		pairs, err := mappingPairs(data, val, "Config.SingleKeyJump")
		if err != nil {
			return err
		}
		for _, p := range pairs {
			if p[0].Value == "ShowPrefix" {
				b, ok, err := yamlBoolValue(data, p[1], "Config.SingleKeyJump")
				if err != nil {
					return err
				}
				if ok {
					cfg.SingleKeyJump.ShowPrefix = b
				}
			}
		}
		return nil
	default:
		return nil
	}
}
