{"command":"cat > line.go <<'EOF'
package main

import (
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

var nextLineID int64

type Line struct {
	ID         int64
	Raw        string // original line text (no trailing newline)
	Display    string // plain text used for filtering/display (ANSI CSI stripped; null display part)
	Output     string // text emitted on finish (null result part or Raw)
	ansiStyles []tcell.Style // per-rune cumulative ANSI style for Display runes, nil if none
	ansiRunes  []rune        // runes of Display (cached)
}

func newLine(raw string, nullMode bool) *Line {
	nextLineID++
	id := nextLineID
	dispPart := raw
	outPart := raw
	if nullMode {
		if idx := strings.IndexByte(raw, 0); idx >= 0 {
			dispPart = raw[:idx]
			outPart = raw[idx+1:]
		}
	}
	plain, styles := parseANSI(dispPart)
	l := &Line{ID: id, Raw: raw, Display: plain, Output: outPart, ansiStyles: styles}
	l.ansiRunes = []rune(plain)
	return l
}

// parseANSI strips CSI sequences and records the cumulative SGR style
// (starting from tcell.StyleDefault) for each rune of the plain text.
// A nil styles slice is returned when no SGR was present at all; individual
// entries equal to StyleDefault indicate "no active ANSI style".
func parseANSI(s string) (string, []tcell.Style) {
	var plain strings.Builder
	var styles []tcell.Style
	cur := tcell.StyleDefault
	hasANSI := false
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			// CSI: scan to final byte 0x40-0x7e
			j := i + 2
			for j < len(s) && !(s[j] >= 0x40 && s[j] <= 0x7e) {
				j++
			}
			if j >= len(s) {
				// unterminated: drop rest
				i = len(s)
				break
			}
			final := s[j]
			params := s[i+2 : j]
			if final == 'm' {
				hasANSI = true
				cur = applySGR(cur, params)
			}
			i = j + 1
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 0 {
			size = 1
		}
		plain.WriteString(s[i : i+size])
		styles = append(styles, cur)
		i += size
	}
	if !hasANSI {
		return plain.String(), nil
	}
	return plain.String(), styles
}

func applySGR(cur tcell.Style, params string) tcell.Style {
	if params == "" {
		return tcell.StyleDefault
	}
	parts := strings.Split(params, ";")
	nums := make([]int, len(parts))
	for i, p := range parts {
		if p == "" {
			nums[i] = -1
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			nums[i] = -1
			continue
		}
		nums[i] = n
	}
	for i := 0; i < len(nums); i++ {
		n := nums[i]
		switch {
		case n == 0:
			cur = tcell.StyleDefault
		case n == 1:
			cur = cur.Bold(true)
		case n == 4:
			cur = cur.Underline(true)
		case n == 7:
			cur = cur.Reverse(true)
		case n >= 30 && n <= 37:
			cur = cur.Foreground(ansiBasicColor(n - 30))
		case n == 39:
			cur = cur.Foreground(tcell.ColorDefault)
		case n >= 40 && n <= 47:
			cur = cur.Background(ansiBasicColor(n - 40))
		case n == 49:
			cur = cur.Background(tcell.ColorDefault)
		case n == 38 || n == 48:
			isFg := n == 38
			if i+1 < len(nums) && nums[i+1] == 5 {
				if i+2 < len(nums) && nums[i+2] >= 0 && nums[i+2] <= 255 {
					c := tcell.PaletteColor(nums[i+2])
					if isFg {
						cur = cur.Foreground(c)
					} else {
						cur = cur.Background(c)
					}
					i += 2
				} else {
					// consume mode token if present
					if i+2 < len(nums) {
						i += 2
					} else {
						i += 1
					}
				}
			} else if i+1 < len(nums) && nums[i+1] == 2 {
				if i+4 < len(nums) {
					r := clamp255(nums[i+2])
					g := clamp255(nums[i+3])
					b := clamp255(nums[i+4])
					c := tcell.NewRGBColor(int32(r), int32(g), int32(b))
					if isFg {
						cur = cur.Foreground(c)
					} else {
						cur = cur.Background(c)
					}
					i += 4
				} else {
					i = len(nums)
				}
			}
		default:
			// ignored
		}
	}
	return cur
}

func clamp255(v int) int {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

func ansiBasicColor(i int) tcell.Color {
	switch i {
	case 0:
		return tcell.ColorBlack
	case 1:
		return tcell.ColorRed
	case 2:
		return tcell.ColorGreen
	case 3:
		return tcell.ColorYellow
	case 4:
		return tcell.ColorBlue
	case 5:
		return tcell.ColorMagenta
	case 6:
		return tcell.ColorCyan
	case 7:
		return tcell.ColorWhite
	}
	return tcell.ColorDefault
}

// runeDisplayWidth returns the terminal cell width of a rune.
// Tab is handled specially by callers.
func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	return runewidth.RuneWidth(r)
}

func stringDisplayWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeDisplayWidth(r)
	}
	return w
}

// sanitizeQueryRunes drops control runes like the original does when a query
// string is set programmatically.
func sanitizeQueryRunes(s string) []rune {
	var out []rune
	for _, r := range s {
		if unicode.IsControl(r) {
			continue
		}
		out = append(out, r)
	}
	return out
}
EOF
gofmt -w line.go"}

