			} else if i+1 < len(nums) && nums[i+1] == 2 {
				if i+4 < len(nums) {
					r := clamp255(nums[i+2])
					g := clamp255(nums[i+3])
					b := clamp255(nums[i+4])
					c := tcell.NewRGBColor(int32(r), int32(g), int32(b))
					if isFg {
						cur = cur.Foreground(c)
					} else {
						cur = cur.Background(c)
					}
					i += 4
				} else {
					i = len(nums)
				}
			}
		default:
			// ignored
		}
	}
	return cur
}

func clamp255(v int) int {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

func ansiBasicColor(i int) tcell.Color {
	switch i {
	case 0:
		return tcell.ColorBlack
	case 1:
		return tcell.ColorRed
	case 2:
		return tcell.ColorGreen
	case 3:
		return tcell.ColorYellow
	case 4:
		return tcell.ColorBlue
	case 5:
		return tcell.ColorMagenta
	case 6:
		return tcell.ColorCyan
	case 7:
		return tcell.ColorWhite
	}
	return tcell.ColorDefault
}

// runeDisplayWidth returns the terminal cell width of a rune.
// Tab is handled specially by callers.
func runeDisplayWidth(r rune) int {
	if r == 0 {
		return 0
	}
	return runewidth.RuneWidth(r)
}

func stringDisplayWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeDisplayWidth(r)
	}
	return w
}

// sanitizeQueryRunes drops control runes like the original does when a query
// string is set programmatically.
func sanitizeQueryRunes(s string) []rune {
	var out []rune
	for _, r := range s {
		if unicode.IsControl(r) {
			continue
		}
		out = append(out, r)
	}
	return out
}
