	Name() string
	// Apply filters source lines with the given raw query. It returns results
	// in display order.
	Apply(source []*Line, query string) []*Result
}

// parseQueryTerms splits a query into positive and negative terms.
func parseQueryTerms(q string) (pos []string, neg []string) {
	for _, tok := range strings.Split(q, " ") {
		if tok == "" {
			continue
		}
		switch {
		case tok == "-":
			pos = append(pos, "-")
		case strings.HasPrefix(tok, "\\-"):
			pos = append(pos, tok[1:])
		case strings.HasPrefix(tok, "-"):
			neg = append(neg, tok[1:])
		default:
			pos = append(pos, tok)
		}
	}
	return
}

type filterKind int

const (
	kindIgnoreCase filterKind = iota
	kindCaseSensitive
	kindSmartCase
	kindIRegexp
	kindRegexp
	kindFuzzy
)

type builtinFilter struct {
	name             string
	kind             filterKind
	fuzzyLongestSort bool
}

func (f *builtinFilter) Name() string { return f.name }

func compilePattern(pat string, ci bool) (*regexp.Regexp, error) {
	if ci {
		pat = "(?i)" + pat
	}
	return regexp.Compile(pat)
}

func (f *builtinFilter) Apply(source []*Line, query string) []*Result {
	pos, neg := parseQueryTerms(query)
	if f.kind == kindFuzzy {
		return f.applyFuzzy(source, pos, neg)
	}
	ci := false
	regexpMode := false
	switch f.kind {
	case kindIgnoreCase:
		ci = true
	case kindCaseSensitive:
		ci = false
	case kindSmartCase:
		ci = true
		// sensitive if any term (pos or neg, as stored after stripping
		// leading '-' / '\-' markers... but original checks the raw
		// query terms) contains an upper-case letter. We check the raw
		// query string: if lowercasing changes it, be sensitive.
		if strings.ToLower(query) != query {
			ci = false
		}
	case kindIRegexp:
		ci = true
		regexpMode = true
	case kindRegexp:
		ci = false
		regexpMode = true
	}
	mk := func(term string) (*regexp.Regexp, error) {
		pat := term
		if !regexpMode {
			pat = regexp.QuoteMeta(term)
		}
		return compilePattern(pat, ci)
	}
	var posRes, negRes []*regexp.Regexp
	for _, t := range pos {
		re, err := mk(t)
		if err != nil {
			return nil
		}
		posRes = append(posRes, re)
	}
	for _, t := range neg {
		re, err := mk(t)
		if err != nil {
			return nil
		}
		negRes = append(negRes, re)
	}
	var out []*Result
	for _, ln := range source {
		target := ln.Display
		excluded := false
		for _, re := range negRes {
			if re.FindStringIndex(target) != nil {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}
		var ranges [][2]int
		ok := true
		for _, re := range posRes {
			idxs := re.FindAllStringIndex(target, -1)
			if idxs == nil {
				ok = false
				break
			}
			for _, ix := range idxs {
				if ix[1] > ix[0] {
					ranges = append(ranges, [2]int{ix[0], ix[1]})
				}
			}
		}
		if !ok {
			continue
		}
		out = append(out, &Result{Line: ln, Matched: ranges})
	}
	return out
}

// fuzzy

func fuzzyCharEqual(a, b rune, ci bool) bool {
	if ci {
		return unicode.SimpleFold(a) == unicode.SimpleFold(b) || foldEqual(a, b)
	}
	return a == b
}

// foldEqual reports whether runes a and b are equal under simple folding.
func foldEqual(a, b rune) bool {
	if a == b {
		return true
	}
	// cycle through the fold orbit of a
	r := unicode.SimpleFold(a)
	for r != a {
		if r == b {
			return true
		}
		r = unicode.SimpleFold(r)
	}
	return false
}

// fuzzyFindGreedy returns rune indices of the leftmost subsequence match.
func fuzzyFindGreedy(line, pat []rune, ci bool) ([]int, bool) {
	if len(pat) == 0 {
		return nil, true
	}
	idxs := make([]int, 0, len(pat))
	j := 0
	for i, lr := range line {
		if fuzzyCharEqual(lr, pat[j], ci) {
			idxs = append(idxs, i)
			j++
			if j == len(pat) {
				return idxs, true
			}
		}
	}
	return nil, false
}

// longestCommonSubstring returns (lineStart, patStart, length) of the
// earliest longest common contiguous substring (in runes).
func longestCommonSubstring(line, pat []rune, ci bool) (int, int, int) {
	bestLen := 0
	bestLine, bestPat := 0, 0
	// DP over suffixes
	prev := make([]int, len(pat)+1)
	cur := make([]int, len(pat)+1)
	for i := 1; i <= len(line); i++ {
		for j := 1; j <= len(pat); j++ {
			if fuzzyCharEqual(line[i-1], pat[j-1], ci) {
				cur[j] = prev[j-1] + 1
				if cur[j] > bestLen {
					bestLen = cur[j]
					bestLine = i - cur[j]
					bestPat = j - cur[j]
				}
			} else {
				cur[j] = 0
			}
		}
		prev, cur = cur, prev
		for j := range cur {
			cur[j] = 0
		}
	}
	return bestLine, bestPat, bestLen
}

// fuzzyFindLongest finds a subsequence alignment anchored on a longest
// common substring. Returns rune indices, anchor length, ok.
func fuzzyFindLongest(line, pat []rune, ci bool) ([]int, int, bool) {
	if len(pat) == 0 {
		return nil, 0, true
	}
	// Try anchors in decreasing length by searching all candidate substrings
	// via the LCS routine on decreasing windows is complex; instead, try the
	// overall LCS anchor, and if the prefix/suffix cannot be completed,
	// fall back progressively by trying every occurrence of substrings of
	// decreasing length.
	type cand struct{ ls, ps, ln int }
	seen := map[cand]bool{}
	tryAnchor := func(ls, ps, ln int) ([]int, bool) {
		// match prefix pat[:ps] as subsequence in line[:ls]
		pre, ok := fuzzyFindGreedy(line[:ls], pat[:ps], ci)
		if !ok {
			return nil, false
		}
		// suffix after anchor
		sufLineStart := ls + ln
		suf, ok := fuzzyFindGreedy(line[sufLineStart:], pat[ps+ln:], ci)
		if !ok {
			return nil, false
		}
		idxs := append([]int{}, pre...)
		for k := 0; k < ln; k++ {
			idxs = append(idxs, ls+k)
		}
		for _, si := range suf {
			idxs = append(idxs, sufLineStart+si)
		}
		return idxs, true
	}
	maxLen := len(pat)
	if len(line) < maxLen {
		maxLen = len(line)
	}
	for ln := maxLen; ln >= 1; ln-- {
		// find all occurrences of common substrings of this length, in
		// order of line position then pattern position
		foundAny := false
		for ls := 0; ls+ln <= len(line); ls++ {
			for ps := 0; ps+ln <= len(pat); ps++ {
				match := true
				for k := 0; k < ln; k++ {
					if !fuzzyCharEqual(line[ls+k], pat[ps+k], ci) {
						match = false
						break
					}
				}
				if !match {
					continue
				}
				foundAny = true
				c := cand{ls, ps, ln}
				if seen[c] {
					continue
				}
				seen[c] = true
				if idxs, ok := tryAnchor(ls, ps, ln); ok {
					return idxs, ln, true
				}
			}
		}
		if foundAny && ln == maxLen {
			// continue searching shorter anchors if completion failed
		}
	}
	return nil, 0, false
}

func (f *builtinFilter) applyFuzzy(source []*Line, pos, neg []string) []*Result {
	ci := true
	for _, t := range pos {
		if strings.ToLower(t) != t {
			ci = false
			break
		}
	}
	// negative terms: case-insensitive literal exclusion
	var negRes []*regexp.Regexp
	for _, t := range neg {
		re, err := compilePattern(regexp.QuoteMeta(t), true)
		if err != nil {
			continue
		}
		negRes = append(negRes, re)
	}
	type scored struct {
		res       *Result
		longest   int
		span      int
		start     int
		lineLen   int
		origIndex int
	}
	var out []*Result
	var scoredList []scored
	for li, ln := range source {
		target := ln.Display
		excluded := false
		for _, re := range negRes {
			if re.FindStringIndex(target) != nil {
				excluded = true
				break
			}
		}
		if excluded {
			continue
		}
		lineRunes := []rune(target)
		// byte offset per rune index
		byteOff := make([]int, len(lineRunes)+1)
		bo := 0
		for ri, r := range lineRunes {
			byteOff[ri] = bo
			bo += len(string(r))
		}
		byteOff[len(lineRunes)] = bo
		var ranges [][2]int
		ok := true
		totalLongest := 0
		totalSpan := 0
		minStart := -1
		for _, term := range pos {
			patRunes := []rune(term)
			var idxs []int
			var anchorLen int
			var found bool
			if f.fuzzyLongestSort {
				idxs, anchorLen, found = fuzzyFindLongest(lineRunes, patRunes, ci)
			} else {
				idxs, found = fuzzyFindGreedy(lineRunes, patRunes, ci)
			}
			if !found {
				ok = false
				break
			}
			totalLongest += anchorLen
			if len(idxs) > 0 {
				totalSpan += idxs[len(idxs)-1] - idxs[0] + 1
				if minStart < 0 || idxs[0] < minStart {
					minStart = idxs[0]
				}
			}
			for _, ri := range idxs {
				ranges = append(ranges, [2]int{byteOff[ri], byteOff[ri+1]})
			}
		}
		if !ok {
			continue
		}
		res := &Result{Line: ln, Matched: ranges}
		if f.fuzzyLongestSort {
			scoredList = append(scoredList, scored{res: res, longest: totalLongest, span: totalSpan, start: minStart, lineLen: len(lineRunes), origIndex: li})
		} else {
			out = append(out, res)
		}
	}
	if f.fuzzyLongestSort {
		sort.SliceStable(scoredList, func(i, j int) bool {
			a, b := scoredList[i], scoredList[j]
			if a.longest != b.longest {
				return a.longest > b.longest
			}
			if a.span != b.span {
				return a.span < b.span
			}
			if a.start != b.start {
				return a.start < b.start
			}
			if a.lineLen != b.lineLen {
				return a.lineLen < b.lineLen
			}
			return a.origIndex < b.origIndex
		})
		for _, s := range scoredList {
			out = append(out, s.res)
		}
	}
	return out
}

// ---- external custom filter ----

type externalFilter struct {
	name string
	cfg  config.CustomFilterConfig
}

func (f *externalFilter) Name() string { return f.name }

func (f *externalFilter) Apply(source []*Line, query string) []*Result {
	threshold := f.cfg.BufferThreshold
	if threshold <= 0 {
		threshold = 100
	}
	args := f.cfg.Args
	if len(args) == 0 {
		args = []string{"$QUERY"}
	}
	realArgs := make([]string, len(args))
	for i, a := range args {
		if a == "$QUERY" {
			realArgs[i] = query
		} else {
			realArgs[i] = a
		}
	}
	var out []*Result
	for start := 0; start < len(source); start += threshold {
		end := start + threshold
		if end > len(source) {
			end = len(source)
		}
		batch := source[start:end]
		var stdin bytes.Buffer
		for _, ln := range batch {
			stdin.WriteString(ln.Raw)
			stdin.WriteByte('\n')
		}
		cmd := exec.Command(f.cfg.Cmd, realArgs...)
		cmd.Stdin = &stdin
		var stdout bytes.Buffer
		cmd.Stdout = &stdout
		// stderr discarded (nil)
		_ = cmd.Run()
		sc := bufio.NewScanner(bytes.NewReader(stdout.Bytes()))
		// Allow long output lines up to a generous size.
		sc.Buffer(make([]byte, 0, 4096), 64*1024*1024)
		for sc.Scan() {
			txt := sc.Text()
			nl := newLine(txt, currentNullMode)
			out = append(out, &Result{Line: nl})
		}
	}
	return out
}

// currentNullMode is set during application construction for use by
// external filters when they synthesize new lines.
var currentNullMode bool

func buildFilters(cfg *config.Config) ([]Filter, map[string]Filter) {
	builtins := []Filter{
		&builtinFilter{name: "IgnoreCase", kind: kindIgnoreCase},
		&builtinFilter{name: "CaseSensitive", kind: kindCaseSensitive},
		&builtinFilter{name: "SmartCase", kind: kindSmartCase},
		&builtinFilter{name: "IRegexp", kind: kindIRegexp},
		&builtinFilter{name: "Regexp", kind: kindRegexp},
		&builtinFilter{name: "Fuzzy", kind: kindFuzzy, fuzzyLongestSort: cfg.FuzzyLongestSort},
	}
	byName := map[string]Filter{}
	list := []Filter{}
	for _, f := range builtins {
		byName[f.Name()] = f
		list = append(list, f)
	}
	for name, cf := range cfg.CustomFilter {
		if _, exists := byName[name]; exists {
			continue
		}
		f := &externalFilter{name: name, cfg: cf}
		byName[name] = f
		list = append(list, f)
	}
	return list, byName
}
