		}
		byteOff[len(lineRunes)] = bo
		var ranges [][2]int
		ok := true
		totalLongest := 0
		totalSpan := 0
		minStart := -1
		for _, term := range pos {
			patRunes := []rune(term)
			var idxs []int
			var anchorLen int
			var found bool
			if f.fuzzyLongestSort {
				idxs, anchorLen, found = fuzzyFindLongest(lineRunes, patRunes, ci)
			} else {
				idxs, found = fuzzyFindGreedy(lineRunes, patRunes, ci)
			}
			if !found {
				ok = false
				break
			}
			totalLongest += anchorLen
			if len(idxs) > 0 {
				totalSpan += idxs[len(idxs)-1] - idxs[0] + 1
				if minStart < 0 || idxs[0] < minStart {
					minStart = idxs[0]
				}
			}
			for _, ri := range idxs {
				ranges = append(ranges, [2]int{byteOff[ri], byteOff[ri+1]})
			}
		}
		if !ok {
			continue
		}
		res := &Result{Line: ln, Matched: ranges}
		if f.fuzzyLongestSort {
			scoredList = append(scoredList, scored{res: res, longest: totalLongest, span: totalSpan, start: minStart, lineLen: len(lineRunes), origIndex: li})
		} else {
			out = append(out, res)
		}
	}
	if f.fuzzyLongestSort {
		sort.SliceStable(scoredList, func(i, j int) bool {
			a, b := scoredList[i], scoredList[j]
			if a.longest != b.longest {
				return a.longest > b.longest
			}
			if a.span != b.span {
				return a.span < b.span
			}
			if a.start != b.start {
				return a.start < b.start
			}
			if a.lineLen != b.lineLen {
				return a.lineLen < b.lineLen
			}
			return a.origIndex < b.origIndex
		})
		for _, s := range scoredList {
			out = append(out, s.res)
		}
	}
	return out
}

// ---- external custom filter ----

type externalFilter struct {
	name string
	cfg  config.CustomFilterConfig
}

func (f *externalFilter) Name() string { return f.name }

func (f *externalFilter) Apply(source []*Line, query string) []*Result {
	threshold := f.cfg.BufferThreshold
	if threshold <= 0 {
		threshold = 100
	}
	args := f.cfg.Args
	if len(args) == 0 {
		args = []string{"$QUERY"}
	}
	realArgs := make([]string, len(args))
	for i, a := range args {
		if a == "$QUERY" {
			realArgs[i] = query
		} else {
			realArgs[i] = a
		}
	}
	var out []*Result
	for start := 0; start < len(source); start += threshold {
		end := start + threshold
		if end > len(source) {
			end = len(source)
		}
		batch := source[start:end]
		var stdin bytes.Buffer
		for _, ln := range batch {
			stdin.WriteString(ln.Raw)
			stdin.WriteByte('\n')
		}
		cmd := exec.Command(f.cfg.Cmd, realArgs...)
		cmd.Stdin = &stdin
		var stdout bytes.Buffer
		cmd.Stdout = &stdout
		// stderr discarded (nil)
		_ = cmd.Run()
		sc := bufio.NewScanner(bytes.NewReader(stdout.Bytes()))
		// Allow long output lines up to a generous size.
		sc.Buffer(make([]byte, 0, 4096), 64*1024*1024)
		for sc.Scan() {
			txt := sc.Text()
			nl := newLine(txt, currentNullMode)
			out = append(out, &Result{Line: nl})
		}
	}
	return out
}

// currentNullMode is set during application construction for use by
// external filters when they synthesize new lines.
var currentNullMode bool

func buildFilters(cfg *config.Config) ([]Filter, map[string]Filter) {
	builtins := []Filter{
		&builtinFilter{name: "IgnoreCase", kind: kindIgnoreCase},
		&builtinFilter{name: "CaseSensitive", kind: kindCaseSensitive},
		&builtinFilter{name: "SmartCase", kind: kindSmartCase},
		&builtinFilter{name: "IRegexp", kind: kindIRegexp},
		&builtinFilter{name: "Regexp", kind: kindRegexp},
		&builtinFilter{name: "Fuzzy", kind: kindFuzzy, fuzzyLongestSort: cfg.FuzzyLongestSort},
	}
	byName := map[string]Filter{}
	list := []Filter{}
	for _, f := range builtins {
		byName[f.Name()] = f
		list = append(list, f)
	}
	for name, cf := range cfg.CustomFilter {
		if _, exists := byName[name]; exists {
			continue
		}
		f := &externalFilter{name: name, cfg: cf}
		byName[name] = f
		list = append(list, f)
	}
	return list, byName
}
EOF
gofmt -w filters.go"}

