// resolveAction resolves an action name (possibly a combined custom action)
// to a list of builtin action names.
func resolveAction(name string, custom map[string][]string, depth int) ([]string, error) {
	if depth > 10 {
		return nil, fmt.Errorf("could not resolve %s: deep recursion", name)
	}
	if subs, ok := custom[name]; ok {
		var out []string
		for _, sub := range subs {
			resolved, err := resolveAction(sub, custom, depth+1)
			if err != nil {
				return nil, err
			}
			out = append(out, resolved...)
		}
		return out, nil
	}
	if _, ok := builtinActions[name]; ok {
		return []string{name}, nil
	}
	return nil, fmt.Errorf("could not resolve %s: no such action", name)
