// convertKeyString converts one comma-separated element of a keymap key
// into a KeyToken.
func convertKeyString(s string) (KeyToken, error) {
	orig := s
	s = strings.TrimSpace(s)
	if s == "" {
		return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
	}
	// Try to peel modifier prefixes for special keys.
	rest := s
	var modC, modM, modS bool
	peeledAny := true
	for peeledAny {
		peeledAny = false
		if strings.HasPrefix(rest, "C-") {
			modC = true
			rest = rest[2:]
			peeledAny = true
		} else if strings.HasPrefix(rest, "M-") {
			modM = true
			rest = rest[2:]
			peeledAny = true
		} else if strings.HasPrefix(rest, "S-") {
			modS = true
			rest = rest[2:]
			peeledAny = true
		}
	}
	if rest == "" {
		return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
	}
	if canon, ok := specialKeyNames[rest]; ok {
		// Build canonical name with modifiers in C-, S-, M- order for
		// special keys, except that a bare special key with only M-
		// uses M-.
		name := canon
		if canon == " " {
			// Space
			if modC && !modM && !modS {
				return KeyToken{Name: "C-Space"}, nil
			}
			if modM && !modC && !modS {
				return KeyToken{Name: "M-Space", Rune: ' ', IsRune: true}, nil
			}
			if !modC && !modM && !modS {
				return KeyToken{Name: " ", Rune: ' ', IsRune: true}, nil
			}
			// other combos fall through to generic naming
			name = "Space"
		}
		if modM {
			// For Ctrl-letter style keys canonical is M-C-x, but for
			// special keys the observed status names are like C-Delete,
			// M-Delete, C-S-Delete. Build in order M- handled below.
			_ = modM
		}
		prefix := ""
		if modC {
			prefix += "C-"
		}
		if modS {
			prefix += "S-"
		}
		if modM {
			// M- comes first when combined with C- for keys whose base
			// already includes a C- form; for plain special keys the
			// event builder emits modifiers in the order we produce
			// in eventKeyToken: alt is the outermost prefix there too.
			prefix = "M-" + prefix
		}
		full := prefix + name
		if canon == " " && !modC && !modM && !modS {
			full = " "
		}
		tok := KeyToken{Name: full}
		if canon == " " {
			tok.Rune = ' '
			tok.IsRune = true
			if modC {
				tok.IsRune = false
				tok.Rune = 0
			}
		}
		return tok, nil
	}
	// Legacy paths.
	// M-<key>: alt modifier on a (possibly Ctrl) key or a rune.
	if strings.HasPrefix(s, "M-") {
		inner := s[2:]
		if inner == "" {
			return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
		}
		if strings.HasPrefix(inner, "C-") {
			// M-C-x form
			rest2 := inner[2:]
			if rest2 == "" {
				return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
			}
			// Ctrl key with alt
			ct, err := ctrlKeyToken(rest2)
			if err != nil {
				return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
			}
			ct.Name = "M-" + ct.Name
			return ct, nil
		}
		// M-<rune> (first rune of inner)
		r := []rune(inner)[0]
		return KeyToken{Name: "M-" + string(r), Rune: r, IsRune: true}, nil
	}
	if strings.HasPrefix(s, "C-") {
		rest2 := s[2:]
		if rest2 == "" {
			return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
		}
		return ctrlKeyToken(rest2)
	}
	if strings.HasPrefix(s, "S-") {
		// Not a special key (handled above): fall back to first rune 'S'.
		return KeyToken{Name: "S", Rune: 'S', IsRune: true}, nil
	}
	// Fallback: first rune.
	r := []rune(s)[0]
	_ = orig
	return KeyToken{Name: string(r), Rune: r, IsRune: true}, nil
}

func ctrlKeyToken(rest string) (KeyToken, error) {
	// rest is after "C-"
	if canon, ok := specialKeyNames[rest]; ok {
		if canon == " " {
			return KeyToken{Name: "C-Space"}, nil
		}
		return KeyToken{Name: "C-" + canon}, nil
	}
	r := []rune(rest)[0]
	switch {
	case r >= 'a' && r <= 'z':
		return KeyToken{Name: "C-" + string(r)}, nil
	case r >= 'A' && r <= 'Z':
		// Unclear; treat as C-<lower>? Original likely falls back.
		return KeyToken{Name: "C-" + string(r)}, nil
	case r == '8':
		return KeyToken{Name: "C-8"}, nil
	case r == '2':
		return KeyToken{Name: "C-Space"}, nil
	case r == '[':
		return KeyToken{Name: "Esc"}, nil
	default:
		// C-], C-\, C-^, C-_, C-/, C-3..7 etc: produce a name that will
		// never match an event token (events for these are ignored).
		return KeyToken{Name: "C-" + string(r)}, nil
	}
}

// parseKeySequence parses a comma-separated key sequence string.
func parseKeySequence(s string) ([]KeyToken, error) {
	parts := strings.Split(s, ",")
	var toks []KeyToken
	for _, p := range parts {
		tok, err := convertKeyString(p)
		if err != nil {
			return nil, fmt.Errorf("unknown key %s: %w", s, err)
		}
		toks = append(toks, tok)
	}
	return toks, nil
}

func seqKey(toks []KeyToken) string {
	names := make([]string, len(toks))
	for i, t := range toks {
		names[i] = t.Name
	}
	return strings.Join(names, "\x00")
}

func seqDisplay(toks []KeyToken) string {
	names := make([]string, len(toks))
	for i, t := range toks {
		names[i] = t.Name
	}
	return strings.Join(names, " ")
}

// ---- tcell event -> KeyToken ----

func modifierPrefixNames(m tcell.ModMask) (ctrl, shift, alt bool) {
	ctrl = m&tcell.ModCtrl != 0
	shift = m&tcell.ModShift != 0
	alt = m&tcell.ModAlt != 0 || m&tcell.ModMeta != 0
	return
}

func buildModName(base string, m tcell.ModMask) string {
	ctrl, shift, alt := modifierPrefixNames(m)
	prefix := ""
	if ctrl {
		prefix += "C-"
	}
	if shift {
		prefix += "S-"
	}
	if alt {
		prefix = "M-" + prefix
	}
	return prefix + base
}

// eventKeyToken converts a tcell key event into a KeyToken. The second
// return value is false if the event should be ignored entirely.
func eventKeyToken(ev *tcell.EventKey) (KeyToken, bool) {
	key := ev.Key()
	mod := ev.Modifiers()
	switch key {
	case tcell.KeyRune:
		r := ev.Rune()
		if r == 0 {
			return KeyToken{}, false
		}
		name := string(r)
		_, _, alt := modifierPrefixNames(mod)
		if alt {
			name = "M-" + name
		}
		return KeyToken{Name: name, Rune: r, IsRune: true}, true
	case tcell.KeyUp:
		return KeyToken{Name: buildModName("^", mod)}, true
	case tcell.KeyDown:
		return KeyToken{Name: buildModName("v", mod)}, true
	case tcell.KeyLeft:
		return KeyToken{Name: buildModName("<", mod)}, true
	case tcell.KeyRight:
		return KeyToken{Name: buildModName(">", mod)}, true
	case tcell.KeyPgUp:
		return KeyToken{Name: buildModName("Pgup", mod)}, true
	case tcell.KeyPgDn:
		return KeyToken{Name: buildModName("Pgdn", mod)}, true
	case tcell.KeyHome:
		return KeyToken{Name: buildModName("Home", mod)}, true
	case tcell.KeyEnd:
		return KeyToken{Name: buildModName("End", mod)}, true
	case tcell.KeyInsert:
		return KeyToken{Name: buildModName("Insert", mod)}, true
	case tcell.KeyDelete:
		return KeyToken{Name: buildModName("Delete", mod)}, true
	case tcell.KeyF1, tcell.KeyF2, tcell.KeyF3, tcell.KeyF4, tcell.KeyF5, tcell.KeyF6,
		tcell.KeyF7, tcell.KeyF8, tcell.KeyF9, tcell.KeyF10, tcell.KeyF11, tcell.KeyF12:
		n := int(key-tcell.KeyF1) + 1
		return KeyToken{Name: buildModName(fmt.Sprintf("F%d", n), mod)}, true
	case tcell.KeyBS, tcell.KeyBackspace2:
		return KeyToken{Name: "BS"}, true
	case tcell.KeyTab:
		return KeyToken{Name: "Tab"}, true
	case tcell.KeyBacktab:
		return KeyToken{Name: "Tab"}, true
	case tcell.KeyEnter:
		return KeyToken{Name: "Enter"}, true
	case tcell.KeyEsc:
		return KeyToken{Name: "Esc"}, true
	case tcell.KeyCtrlSpace:
		return KeyToken{}, false
	}
	// Ctrl keys by code.
	if key >= tcell.KeyCtrlA && key <= tcell.KeyCtrlZ {
		letter := rune('a' + int(key-tcell.KeyCtrlA))
		name := "C-" + string(letter)
		_, _, alt := modifierPrefixNames(mod)
		if alt {
			name = "M-" + name
		}
		return KeyToken{Name: name}, true
	}
	// KeyCtrlJ (LF, 10) and KeyCtrlM are Enter aliases in tcell
	// (KeyEnter == KeyCR == 13, KeyCtrlJ == 10). The switch above handles 13.
	if int(key) == 10 {
		return KeyToken{Name: "Enter"}, true
	}
	return KeyToken{}, false
}

func mouseKeyToken(ev *tcell.EventMouse) (KeyToken, bool) {
	btn := ev.Buttons()
	switch {
	case btn&tcell.Button1 != 0:
		return KeyToken{Name: "MouseLeft"}, true
	case btn&tcell.Button2 != 0:
		return KeyToken{Name: "MouseMiddle"}, true
	case btn&tcell.Button3 != 0:
		return KeyToken{Name: "MouseRight"}, true
	}
	return KeyToken{}, false
}
