func parseHeight(spec string) (heightSpec, error) {
	trimmed := strings.TrimSpace(spec)
	if trimmed == "" {
		return heightSpec{}, nil
	}
	if strings.HasSuffix(trimmed, "%") {
		numStr := strings.TrimSuffix(trimmed, "%")
