func (a *App) startReader() {
	go func() {
		maxKB := a.cfg.MaxScanBufferSize
		if maxKB <= 0 {
			maxKB = 256
		}
		maxSize := maxKB * 1024
		sc := bufio.NewScanner(a.inputSource)
		initCap := 4096
		if maxSize <= initCap {
			initCap = 64
			if maxSize <= 64 {
