	inputErr    atomic.Value // string
	readyCh     chan struct{}
	readyOnce   sync.Once
	doneCh      chan struct{}
	notifyCh    chan struct{}

	// state (main goroutine only)
	queryRunes   []rune
	caret        int
	savedQuery   []rune // for ToggleQuery
	frozen       []*Line
	isFrozen     bool
	displayed    []*Result // currently displayed results
	filtered     []*Result // last filter results (pre-zoom snapshot source)
	selIndex     int
