}

func setupApp(cli *cliOptions) (*App, error) {
	cfg, err := loadConfig(cli.Rcfile)
	if err != nil {
		return nil, fmt.Errorf("failed to setup peco: failed to setup configuration: %w", err)
	}
	app := &App{
		cli:             cli,
		cfg:             cfg,
		prompt:          "QUERY>",
		savedSel:        map[*Line]bool{},
		readyCh:         make(chan struct{}),
		doneCh:          make(chan struct{}),
		notifyCh:        make(chan struct{}, 1),
		statusMsg:       "Waiting for input...",
		initialSelIndex: cli.InitialIndex,
	}
	if cli.InitialIndex < 0 {
		app.selIndex = 0
		app.initialSelIndex = 0
	} else {
		app.selIndex = cli.InitialIndex
	}
	if err := app.applyConfig(); err != nil {
		return nil, fmt.Errorf("failed to setup peco: failed to apply configuration: %w", err)
	}
	// input source
	if err := app.setupInputSource(); err != nil {
		return nil, err
	}
	return app, nil
}

func (a *App) applyConfig() error {
	cfg := a.cfg
	cli := a.cli
	// OnCancel
	a.onCancel = cfg.OnCancel
	if cli.OnCancel != "" {
		var oc config.OnCancelBehavior
		if err := oc.Set(cli.OnCancel); err != nil {
			return fmt.Errorf("invalid --on-cancel value: %w", err)
		}
		a.onCancel = oc
	}
	if a.onCancel == "" {
		a.onCancel = config.OnCancelSuccess
	}
	// Height
	hstr := cfg.Height
	if cli.Height != "" {
		hstr = cli.Height
	}
	if hstr != "" {
		hs, err := parseHeight(hstr)
		if err != nil {
			return fmt.Errorf("failed to parse height specification: %w", err)
		}
		a.height = hs
	}
	// simple fields
	a.layout = cfg.Layout
	if cli.Layout != "" {
		a.layout = cli.Layout
	}
	if a.layout == "" {
		a.layout = "top-down"
	}
	if cfg.Prompt != "" {
		a.prompt = cfg.Prompt
	}
	if cli.Prompt != "" {
		a.prompt = cli.Prompt
	}
	a.selectionPrefix = cfg.SelectionPrefix
	if cli.SelectionPrefix != "" {
		a.selectionPrefix = cli.SelectionPrefix
	}
	a.ansiEnabled = cfg.ANSI || cli.ANSI
	a.nullMode = cli.Null
	currentNullMode = cli.Null
	a.execCmd = cli.Exec

	// filters list (needed for initial filter)
	a.filters, a.filtersByName = buildFilters(cfg)

	// keymap
	if err := a.populateKeymap(); err != nil {
		return fmt.Errorf("failed to populate keymap: %w", err)
	}
	// initial filter
	fname := cfg.InitialFilter
	if cli.InitialFilter != "" {
		fname = cli.InitialFilter
	}
	if fname == "" {
		fname = "IgnoreCase"
	}
	f, ok := a.filtersByName[fname]
	if !ok {
		return fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
	}
	for i, ff := range a.filters {
		if ff == f {
			a.filterIndex = i
			break
		}
	}
	// query
	a.queryRunes = sanitizeQueryRunes(cli.Query)
	a.caret = len(a.queryRunes)
	return nil
}

func (a *App) populateKeymap() error {
	a.bindings = map[string][]string{}
	addBinding := func(keyStr string, resolved []string) error {
		toks, err := parseKeySequence(keyStr)
		if err != nil {
			return err
		}
		a.bindings[seqKey(toks)] = resolved
		return nil
	}
	for k, act := range defaultKeymap {
		_ = addBinding(k, []string{act})
	}
	// custom bindings in map iteration order
	for keyStr, actName := range a.cfg.Keymap {
		resolved, err := resolveAction(actName, a.cfg.Action, 0)
		if err != nil {
			return fmt.Errorf("failed to apply key bindings: failed to resolve action name %s: %w", actName, err)
		}
		if err := addBinding(keyStr, resolved); err != nil {
			return fmt.Errorf("failed to apply key bindings: %w", err)
		}
	}
	return nil
}

func (a *App) setupInputSource() error {
	if len(a.cli.Args) > 0 {
		f, err := os.Open(a.cli.Args[0])
		if err != nil {
			return fmt.Errorf("failed to setup input source: failed to open file for input: %w", err)
		}
		a.inputSource = f
		return nil
	}
	if term.IsTerminal(int(os.Stdin.Fd())) {
		return fmt.Errorf("failed to setup input source: you must supply something to work with via filename or stdin")
	}
	a.inputSource = os.Stdin
	return nil
}

func (a *App) currentFilter() Filter {
	return a.filters[a.filterIndex]
}

func (a *App) queryString() string {
	return string(a.queryRunes)
}

func (a *App) startReader() {
	go func() {
		maxKB := a.cfg.MaxScanBufferSize
		if maxKB <= 0 {
			maxKB = 256
		}
		maxSize := maxKB * 1024
		sc := bufio.NewScanner(a.inputSource)
		initCap := 4096
		if maxSize <= initCap {
			initCap = 64
			if maxSize <= 64 {
				initCap = 1
			}
		}
		sc.Buffer(make([]byte, 0, initCap), maxSize)
		sc.Split(bufio.ScanLines)
		bufSize := a.cli.BufferSize
		for sc.Scan() {
			ln := newLine(sc.Text(), a.nullMode)
			a.rawMu.Lock()
			if bufSize > 0 {
				for len(a.raw) >= bufSize {
					a.raw = a.raw[1:]
				}
			}
			a.raw = append(a.raw, ln)
			a.rawMu.Unlock()
			a.readyOnce.Do(func() { close(a.readyCh) })
			select {
			case a.notifyCh <- struct{}{}:
			default:
			}
		}
		if err := sc.Err(); err != nil {
			a.inputErr.Store(err.Error())
		}
		a.inputDone.Store(true)
		a.readyOnce.Do(func() { close(a.readyCh) })
		close(a.doneCh)
		select {
		case a.notifyCh <- struct{}{}:
		default:
		}
	}()
}

func (a *App) rawSnapshot() []*Line {
	a.rawMu.Lock()
	defer a.rawMu.Unlock()
	out := make([]*Line, len(a.raw))
	copy(out, a.raw)
	return out
}

func (a *App) rawLen() int {
	a.rawMu.Lock()
	defer a.rawMu.Unlock()
	return len(a.raw)
}

func (a *App) sourceLines() []*Line {
	if a.isFrozen {
		out := make([]*Line, len(a.frozen))
		copy(out, a.frozen)
		return out
	}
	return a.rawSnapshot()
}

// ---- query execution ----

type queryJob struct {
	gen     int
	source  []*Line
	query   string
	filter  Filter
	isInputChange bool
}

type queryResult struct {
	gen     int
	results []*Result
	query   string
	filter  Filter
}

type queryWorker struct {
	jobs    chan queryJob
	results chan queryResult
}

func startQueryWorker() *queryWorker {
	w := &queryWorker{jobs: make(chan queryJob, 1), results: make(chan queryResult, 1)}
	go func() {
		for job := range w.jobs {
			res := job.filter.Apply(job.source, job.query)
			w.results <- queryResult{gen: job.gen, results: res, query: job.query, filter: job.filter}
		}
	}()
	return w
}

// requestQuery starts an async query execution.
// reason: "query" (query text changed), "filter", "input", "refresh", "force" (recompute from base)
func (a *App) requestQuery(reason string) {
	a.queryGen++
	gen := a.queryGen
	curFilter := a.currentFilter()
	curQuery := a.queryString()
	var source []*Line
	reuse := false
	if reason != "input" && reason != "force" && a.hasExecuted && a.lastFilter == curFilter && a.lastQuery != "" && strings.HasPrefix(curQuery, a.lastQuery) {
		reuse = true
	}
	if reason == "input" {
		reuse = false
	}
	if reuse {
		for _, r := range a.filtered {
			source = append(source, r.Line)
		}
	} else {
		source = a.sourceLines()
	}
	a.runningQuery = true
	a.displayed = nil
	a.statusMsg = "Running query..."
	a.keyDisplay = ""
	a.draw()
	job := queryJob{gen: gen, source: source, query: curQuery, filter: curFilter, isInputChange: reason == "input"}
	// replace queued job if any
	select {
	case <-a.queryWorker.jobs:
	default:
	}
	a.queryWorker.jobs <- job
}

func (a *App) applyQueryResult(res queryResult) {
	if res.gen != a.queryGen {
		return
	}
	a.runningQuery = false
	if a.statusMsg == "Running query..." || a.statusMsg == "Waiting for input..." {
		a.statusMsg = ""
	}
	a.filtered = res.results
	a.displayed = res.results
	a.lastQuery = res.query
	a.lastFilter = res.filter
	a.hasExecuted = true
	a.lastExecRawCount = a.rawLen()
	a.clampSelection()
	a.draw()
	if a.pendingEarly || a.inputDone.Load() {
		a.pendingEarly = false
		a.checkEarlyExitAfterFilter()
	}
}

func (a *App) clampSelection() {
	if a.selIndex < 0 {
		a.selIndex = 0
	}
	if len(a.displayed) > 0 && a.selIndex > len(a.displayed)-1 {
		a.selIndex = len(a.displayed) - 1
	}
}

// setQueryRunes replaces the query, clearing saved selections when
// non-sticky and the query actually changed.
func (a *App) setQueryRunes(r []rune) {
	old := a.queryString()
	a.queryRunes = r
	if a.caret > len(r) {
		a.caret = len(r)
	}
	newQ := string(r)
	if old != newQ {
		if !a.cfg.StickySelection {
			a.savedSel = map[*Line]bool{}
		}
		a.requestQuery("query")
	} else {
		a.draw()
	}
}

func (a *App) modifyQuery(fn func(r []rune, caret int) ([]rune, int)) {
	nr, nc := fn(a.queryRunes, a.caret)
	a.caret = nc
	a.setQueryRunes(nr)
}

// ---- termination / output ----

func (a *App) selectedOutputLines() []*Line {
	if len(a.savedSel) > 0 {
		// collect in raw/source ID order
		var lines []*Line
		for ln := range a.savedSel {
			lines = append(lines, ln)
		}
		// sort by ID
		for i := 1; i < len(lines); i++ {
			for j := i; j > 0 && lines[j].ID < lines[j-1].ID; j-- {
				lines[j], lines[j-1] = lines[j-1], lines[j]
			}
		}
		return lines
	}
	if len(a.displayed) > 0 && a.selIndex >= 0 && a.selIndex < len(a.displayed) {
		return []*Line{a.displayed[a.selIndex].Line}
	}
	return nil
}

func (a *App) outputTextForLines(lines []*Line, forExec bool) string {
	var b strings.Builder
	for _, ln := range lines {
		if forExec {
			b.WriteString(ln.Raw)
		} else {
			b.WriteString(ln.Output)
		}
		b.WriteByte('\n')
	}
	return b.String()
}

func (a *App) printResults(lines []*Line) {
	if a.cli.PrintQuery {
		fmt.Fprintln(os.Stdout, a.queryString())
	}
	for _, ln := range lines {
		fmt.Fprintln(os.Stdout, ln.Output)
	}
}

func (a *App) doFinish() {
	if a.execCmd != "" {
		a.doExec()
		return
	}
	lines := a.selectedOutputLines()
	a.finishScreen()
	a.printResults(lines)
	a.terminated = true
	a.finished = true
}

func (a *App) doExec() {
	lines := a.selectedOutputLines()
	input := a.outputTextForLines(lines, true)
	// Suspend screen
	if a.screen != nil {
		a.screen.Suspend()
	}
	cmd := exec.Command("/bin/sh", "-c", a.execCmd)
	cmd.Stdin = strings.NewReader(input)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if err != nil {
		if a.screen != nil {
			a.screen.Fini()
			a.screenDone = true
		}
		a.terminated = true
		a.finished = true
		a.execErr = err
		return
	}
	if a.screen != nil {
		a.screen.Resume()
	}
	a.draw()
}

// execErr is set when an exec command fails.
func (a *App) doCancel() {
	a.finishScreen()
	a.terminated = true
	a.cancelled = true
}

func (a *App) finishScreen() {
	if a.screen != nil && !a.screenDone {
		a.screen.Fini()
		a.screenDone = true
	}
}

// checkEarlyExitOnDone is called when input finishes, before the initial
// filter result has necessarily been applied. It handles the raw-count==1
// select-1 fast path and exit-0.
func (a *App) checkEarlyExitOnDone() bool {
	rawCount := a.rawLen()
	if a.cli.Exit0 && rawCount == 0 {
		a.finishScreen()
		a.terminated = true
		a.earlyExit1 = true
		return true
	}
	if a.cli.Select1 && !a.cli.SelectAll && rawCount == 1 {
		// Use the unclamped initial selection index.
		var lines []*Line
		if a.initialSelIndex == 0 {
			snap := a.rawSnapshot()
			if len(snap) == 1 {
				lines = snap
			}
		}
		a.finishScreen()
		a.printResults(lines)
		a.terminated = true
		a.finished = true
		return true
	}
	return false
}

func (a *App) checkEarlyExitAfterFilter() bool {
	if a.terminated {
		return true
	}
	if !a.inputDone.Load() {
		return false
	}
	rawCount := a.rawLen()
	if a.cli.Exit0 && rawCount == 0 {
		a.finishScreen()
		a.terminated = true
		a.earlyExit1 = true
		return true
	}
	if a.cli.SelectAll {
		var lines []*Line
		for _, r := range a.filtered {
			lines = append(lines, r.Line)
		}
		a.finishScreen()
		a.printResults(lines)
		a.terminated = true
		a.finished = true
		return true
	}
	if a.cli.Select1 {
		if rawCount == 1 {
			// handled in OnDone fast path before clamp in most cases;
			// if we reach here selection was clamped.
			var lines []*Line
			snap := a.rawSnapshot()
			if len(snap) == 1 && a.initialSelIndex == 0 {
				lines = snap
			}
			a.finishScreen()
			a.printResults(lines)
			a.terminated = true
			a.finished = true
			return true
		}
		if len(a.filtered) == 1 {
			lines := a.selectedOutputLines()
			// selectedOutputLines uses savedSel (empty here) -> current
			a.finishScreen()
			a.printResults(lines)
			a.terminated = true
			a.finished = true
			return true
		}
	}
	return false
}

// screenFailedEarlyExit is invoked when screen creation/init fails; if the
// input is already finished and an early-exit condition applies, it performs
// it and returns (exitCode, true).
func (a *App) screenFailedEarlyExit() (int, bool) {
	if !(a.cli.Select1 || a.cli.SelectAll || a.cli.Exit0) {
		return 0, false
	}
	// give the reader a brief chance to finish if it is about to
	deadline := time.Now().Add(5 * time.Millisecond)
	for !a.inputDone.Load() && time.Now().Before(deadline) {
		time.Sleep(100 * time.Microsecond)
	}
	if !a.inputDone.Load() {
		return 0, false
	}
	rawCount := a.rawLen()
	if a.cli.Exit0 && rawCount == 0 {
		return 1, true
	}
	// Compute filtered results synchronously.
	source := a.sourceLines()
	res := a.currentFilter().Apply(source, a.queryString())
	a.filtered = res
	a.displayed = res
	if a.cli.SelectAll {
		var lines []*Line
		for _, r := range res {
			lines = append(lines, r.Line)
		}
		a.printResults(lines)
		return 0, true
	}
	if a.cli.Select1 {
		if rawCount == 1 {
			var lines []*Line
			if a.initialSelIndex == 0 {
				lines = a.rawSnapshot()
			}
			a.printResults(lines)
			return 0, true
		}
		if len(res) == 1 {
			a.clampSelection()
			lines := a.selectedOutputLines()
			a.printResults(lines)
			return 0, true
		}
	}
	return 0, false
}

// ---- run loop ----

func (a *App) Run(sigCh chan os.Signal) (int, error) {
	a.queryWorker = startQueryWorker()
	// Allocate raw buffer with capacity = BufferSize when positive (mirrors
	// original allocation behaviour, including panic on absurd sizes).
	if a.cli.BufferSize > 0 {
		a.raw = make([]*Line, 0, a.cli.BufferSize)
	}
	a.startReader()
	// Wait for first input or EOF (or signal) before initializing screen.
	select {
	case <-a.readyCh:
	case sig := <-sigCh:
		return 1, fmt.Errorf("received signal: %s", sig.String())
	}
	// Initialize screen.
	scr, err := tcell.NewScreen()
	if err != nil {
		if code, ok := a.screenFailedEarlyExit(); ok {
			return code, nil
		}
		return 1, fmt.Errorf("failed to initialize screen: failed to create tcell screen: %w", err)
	}
	if err := scr.Init(); err != nil {
		if code, ok := a.screenFailedEarlyExit(); ok {
			return code, nil
		}
		return 1, fmt.Errorf("failed to initialize screen: failed to initialize tcell screen: %w", err)
	}
	a.screen = scr
	scr.EnableMouse()
	scr.SetStyle(tcell.StyleDefault)
	scr.HideCursor()

	// Terminal event pump.
	evCh := make(chan tcell.Event, 32)
	go func() {
		for {
			ev := scr.PollEvent()
			if ev == nil {
				return
			}
			evCh <- ev
		}
	}()

	// Initial query execution. If input is already done, the select-1
	// raw fast path may apply before clamping.
	if a.inputDone.Load() {
		if a.checkEarlyExitOnDone() {
			return a.exitCode(), a.execError()
		}
		// Report scanner error if any.
		if v := a.inputErr.Load(); v != nil {
			if s, ok := v.(string); ok && s != "" {
				a.statusMsg = "Error reading input: " + s
			}
		}
	}
	a.requestQuery("force")
	a.rawCount = a.rawLen()
	a.draw()

	ticker := time.NewTicker(20 * time.Millisecond)
	defer ticker.Stop()
	inputDoneHandled := a.inputDone.Load()

	for !a.terminated {
		select {
		case sig := <-sigCh:
			a.finishScreen()
			return 1, fmt.Errorf("received signal: %s", sig.String())
		case ev := <-evCh:
			a.handleEvent(ev)
		case res := <-a.queryWorker.results:
			a.applyQueryResult(res)
		case <-a.notifyCh:
			// input changed
			if a.inputDone.Load() && !inputDoneHandled {
				inputDoneHandled = true
				if v := a.inputErr.Load(); v != nil {
					if s, ok := v.(string); ok && s != "" {
						a.statusMsg = "Error reading input: " + s
						a.keyDisplay = ""
					}
				}
				if a.checkEarlyExitOnDone() {
					break
				}
				a.pendingEarly = true
			}
			a.requestQuery("input")
		case <-ticker.C:
			// Expire transient key display.
			if a.keyDisplay != "" && !a.keyDisplayExp.IsZero() && time.Now().After(a.keyDisplayExp) {
				a.keyDisplay = ""
				if !a.pendingIsPrefix {
					a.pending = nil
				}
				a.draw()
			}
		}
	}
	return a.exitCode(), a.execError()
}

func (a *App) exitCode() int {
	if a.execErr != nil {
		return 1
	}
	if a.earlyExit1 {
		return 1
	}
	if a.cancelled {
		if a.onCancel == config.OnCancelError {
			return 1
		}
		return 0
	}
	return 0
}

func (a *App) execError() error {
	if a.execErr != nil {
		return fmt.Errorf("failed to execute command: %w", a.execErr)
	}
	return nil
}

