	for x < infoX {
		a.setCell(x, g.promptRow, ' ', nil, queryStyle)
		x++
	}
	// info with Basic style (clip if infoX negative)
	a.printRunes(infoX, g.promptRow, styles.Basic.TCell, info, -1)
}

func runeIndexForByte(s string, byteIdx int) int {
	n := 0
	for i := range s {
		if i == byteIdx {
			return n
		}
		n++
	}
	return n
}

func (a *App) drawStatus(g viewGeom) {
	if a.cfg.SuppressStatusMsg {
		return
	}
	text := ""
	if a.keyDisplay != "" {
		text = a.keyDisplay
	} else if a.statusMsg != "" {
		text = a.statusMsg
	}
	if text == "" {
		return
	}
