	if cx >= 0 && cx < w && cy >= 0 && cy < g.h {
		scr.ShowCursor(cx, cy)
	}
	scr.Show()
}

func (a *App) cursorPos(g viewGeom) (int, int) {
	x := stringDisplayWidth(a.prompt) + 1
	for i := 0; i < a.caret && i < len(a.queryRunes); i++ {
		x += runeDisplayWidth(a.queryRunes[i])
	}
	return x, g.promptRow
}

func (a *App) drawPrompt(g viewGeom) {
	styles := a.cfg.Style
	filterName := a.currentFilter().Name()
	info := fmt.Sprintf("%s [%d (%d/%d)]", filterName, len(a.displayed), g.page+1, g.totalPages)
	infoW := stringDisplayWidth(info)
	infoX := g.w - infoW
	queryStyle := styles.Query.TCell
	cursorStyle := styles.QueryCursor.TCell
	if cursorStyle == tcell.StyleDefault {
		cursorStyle = queryStyle.Reverse(true)
	}
	// Build cells for prompt area
	x := 0
	// Prompt text with Prompt style
	x = a.printRunes(x, g.promptRow, styles.Prompt.TCell, a.prompt, infoX)
	// space separator + query with Query style, caret cell with cursor style
	type cell struct {
		r     rune
		style tcell.Style
	}
	// We draw char by char to handle caret and wide/combining through printRunesStyled
	// Construct a display string: " " + query, with a placeholder space at caret==len
	qstr := " " + string(a.queryRunes)
	caretPos := a.caret + 1 // in terms of rune index into qstr runes
	if a.caret >= len(a.queryRunes) {
		qstr += " "
		caretPos = len([]rune(qstr)) - 1
	}
	qrunes := []rune(qstr)
	// Map byte index to rune index for styleFn: styleFn receives byteIdx; recompute
	x = a.printRunesStyled(x, g.promptRow, qstr, infoX, func(r rune, byteIdx int) tcell.Style {
		ri := runeIndexForByte(qstr, byteIdx)
		if ri == caretPos {
			return cursorStyle
		}
		return queryStyle
	})
	_ = qrunes
	// pad with Query style to infoX
	for x < infoX {
		a.setCell(x, g.promptRow, ' ', nil, queryStyle)
		x++
	}
	// info with Basic style (clip if infoX negative)
	a.printRunes(infoX, g.promptRow, styles.Basic.TCell, info, -1)
}

func runeIndexForByte(s string, byteIdx int) int {
	n := 0
	for i := range s {
		if i == byteIdx {
			return n
		}
		n++
	}
	return n
}

func (a *App) drawStatus(g viewGeom) {
	if a.cfg.SuppressStatusMsg {
		return
	}
	text := ""
	if a.keyDisplay != "" {
		text = a.keyDisplay
	} else if a.statusMsg != "" {
		text = a.statusMsg
	}
	if text == "" {
		return
	}
	style := tcell.StyleDefault.Bold(true).Reverse(true)
	tw := stringDisplayWidth(text)
	x := g.w - tw
	a.printRunes(x, g.statusRow, style, text, -1)
}

func (a *App) resultBaseStyle(res *Result, isCurrent, isSaved bool) tcell.Style {
	if a.selectionPrefix != "" {
		return tcell.StyleDefault
	}
	if isCurrent {
		return a.cfg.Style.Selected.TCell
	}
	if isSaved {
		return a.cfg.Style.SavedSelection.TCell
	}
	if res.Context {
		return a.cfg.Style.Context.TCell
	}
	return a.cfg.Style.Basic.TCell
}

func (a *App) drawResultRow(g viewGeom, row, idx, idxInPage int) {
	res := a.displayed[idx]
	ln := res.Line
	isCurrent := idx == a.selIndex
	isSaved := a.savedSel[ln]
	base := a.resultBaseStyle(res, isCurrent, isSaved)
	x := 0
	// selection prefix
	if a.selectionPrefix != "" {
		offset := len(a.selectionPrefix) + 1 // bytes, matching original bug
		if isCurrent {
			a.printRunes(0, row, tcell.StyleDefault, a.selectionPrefix, -1)
		} else if isSaved {
			a.setCell(0, row, '*', nil, tcell.StyleDefault)
		}
		x = offset
	}
	// single-key-jump label
	showLabel := a.jumpMode || a.cfg.SingleKeyJump.ShowPrefix
	if showLabel {
		label := byte(' ')
		if idxInPage < len(jumpLabels) {
			label = jumpLabels[idxInPage]
		}
		labelStyle := base.Bold(true).Reverse(true)
		a.setCell(x, row, rune(label), nil, labelStyle)
		a.setCell(x+1, row, ' ', nil, base)
		x += 2
	}
	contentX := x
	plain := ln.Display
	if plain == "" {
		a.setCell(contentX, row, ' ', nil, base)
		return
	}
	// Precompute matched byte set
	matched := map[int]bool{}
	for _, rg := range res.Matched {
		for b := rg[0]; b < rg[1]; b++ {
			matched[b] = true
		}
	}
	matchedStyle := a.cfg.Style.Matched.TCell
	// horizontal scroll: skip hscroll columns of the plain text
	a.printLineWithHScroll(contentX, row, g.w, ln, base, matched, matchedStyle, isCurrent, isSaved, res.Context)
}

func (a *App) printLineWithHScroll(x, y, maxX int, ln *Line, base tcell.Style, matched map[int]bool, matchedStyle tcell.Style, isCurrent, isSaved, isContext bool) {
	plain := ln.Display
	cx := x
	skipped := 0
	var pendingMain rune
	var pendingComb []rune
	var pendingStyle tcell.Style
	pendingX := 0
	hasPending := false
	flush := func() {
		if hasPending {
			a.setCell(pendingX, y, pendingMain, pendingComb, pendingStyle)
			hasPending = false
			pendingComb = nil
		}
	}
	runeIdx := -1
	for byteIdx, r := range plain {
		runeIdx++
		if r == '\t' {
			flush()
			// tab width based on position within line content (skipped + drawn)
			curCol := skipped + (cx - x)
			if hasPending {
				_ = curCol
			}
			next := ((curCol / 4) + 1) * 4
			for curCol < next {
				if skipped < a.hscroll {
					skipped++
					curCol++
					continue
				}
				if cx >= maxX {
					return
				}
				st := a.charStyle(ln, runeIdx, byteIdx, base, matched, matchedStyle, isCurrent, isSaved, isContext)
				a.setCell(cx, y, ' ', nil, st)
				cx++
				curCol++
			}
			continue
		}
		w := runeDisplayWidth(r)
		if w == 0 {
			if hasPending && isCombining(r) {
				pendingComb = append(pendingComb, r)
			}
			continue
		}
		flush()
		if skipped+w <= a.hscroll {
			skipped += w
			continue
		}
		if skipped < a.hscroll {
			// straddling cluster: skip it, advance cx by remainder
			remainder := (skipped + w) - a.hscroll
			skipped = a.hscroll
			cx += remainder
			continue
		}
		if cx >= maxX {
			return
		}
		if cx+w > maxX {
			return
		}
		pendingMain = r
		pendingStyle = a.charStyle(ln, runeIdx, byteIdx, base, matched, matchedStyle, isCurrent, isSaved, isContext)
		pendingX = cx
		hasPending = true
		cx += w
	}
	flush()
	if cx == x {
		// nothing drawn (e.g. hscroll beyond end): still mark first cell
		// only if the line itself was empty; callers handle empty.
	}
}

func (a *App) charStyle(ln *Line, runeIdx, byteIdx int, base tcell.Style, matched map[int]bool, matchedStyle tcell.Style, isCurrent, isSaved, isContext bool) tcell.Style {
	if matched[byteIdx] {
		mfg, _, mattrs := matchedStyle.Decompose()
		_, bbg, _ := base.Decompose()
		st := tcell.StyleDefault.Foreground(mfg).Background(bbg)
		st = applyAttrs(st, mattrs)
		return st
	}
	// ANSI only applies on Basic (non-selected/saved/context) lines, or in
	// selection-prefix mode where base is StyleDefault.
	applyANSI := a.ansiEnabled && ln.ansiStyles != nil && !isCurrent && !isSaved && !isContext
	if a.selectionPrefix != "" {
		applyANSI = a.ansiEnabled && ln.ansiStyles != nil
	}
	if applyANSI && runeIdx >= 0 && runeIdx < len(ln.ansiStyles) {
		ansiSt := ln.ansiStyles[runeIdx]
		if ansiSt != tcell.StyleDefault {
			afg, abg, aattrs := ansiSt.Decompose()
			bfg, bbg, _ := base.Decompose()
			fg := afg
			if fg == tcell.ColorDefault {
				fg = bfg
			}
			bg := abg
			if bg == tcell.ColorDefault {
				bg = bbg
			}
			st := tcell.StyleDefault.Foreground(fg).Background(bg)
			st = applyAttrs(st, aattrs)
			return st
		}
	}
	return base
}

func applyAttrs(st tcell.Style, attrs tcell.AttrMask) tcell.Style {
	if attrs&tcell.AttrBold != 0 {
		st = st.Bold(true)
	}
	if attrs&tcell.AttrUnderline != 0 {
		st = st.Underline(true)
	}
	if attrs&tcell.AttrReverse != 0 {
		st = st.Reverse(true)
	}
	if attrs&tcell.AttrBlink != 0 {
		st = st.Blink(true)
	}
	if attrs&tcell.AttrDim != 0 {
		st = st.Dim(true)
	}
	if attrs&tcell.AttrItalic != 0 {
		st = st.Italic(true)
	}
	if attrs&tcell.AttrStrikeThrough != 0 {
		st = st.StrikeThrough(true)
	}
	return st
}

