// ---- event handling ----

func (a *App) handleEvent(ev tcell.Event) {
	switch e := ev.(type) {
	case *tcell.EventResize:
		a.screen.Sync()
		a.draw()
	case *tcell.EventKey:
		tok, ok := eventKeyToken(e)
		if !ok {
			return
		}
		a.handleKey(tok)
	case *tcell.EventMouse:
		tok, ok := mouseKeyToken(e)
		if !ok {
			return
		}
		a.handleKey(tok)
	}
}

func (a *App) setKeyDisplayTransient(s string) {
	a.keyDisplay = s
	a.keyDisplayExp = time.Now().Add(500 * time.Millisecond)
}

func (a *App) handleKey(tok KeyToken) {
	// SingleKeyJump interception for plain lowercase letters.
	if a.jumpMode && tok.IsRune && tok.Rune >= 'a' && tok.Rune <= 'z' && len(tok.Name) == 1 {
		pos := strings.IndexByte(jumpLabels, byte(tok.Rune))
		if pos >= 0 {
			g := a.geometry()
			target := g.pageStart + pos
			if target >= 0 && target < len(a.displayed) {
				a.jumpMode = false
				a.selIndex = target
				a.actFinish()
				return
			}
		}
		a.setKeyDisplayTransient(tok.Name)
		a.draw()
		return
	}
	if a.jumpMode && tok.IsRune {
		// Non-jump printable keys are swallowed (not inserted).
		// But if the key is bound to an action, allow normal processing below.
		single := seqKey([]KeyToken{tok})
		if _, bound := a.bindings[single]; !bound && len(a.pending) == 0 {
			a.setKeyDisplayTransient(tok.Name)
			a.draw()
			return
		}
	}
	a.pending = append(a.pending, tok)
	seq := seqKey(a.pending)
	disp := seqDisplay(a.pending)
	resolved, exact := a.bindings[seq]
	isPrefix := a.isSeqPrefix(seq)
	if exact && !isPrefix {
		a.pending = nil
		a.pendingIsPrefix = false
		a.setKeyDisplayTransient(disp)
		for _, name := range resolved {
			if fn, ok := builtinActions[name]; ok {
				fn(a)
				if a.terminated {
					return
				}
			}
		}
		// Actions that set their own status message clear keyDisplay.
		if !a.runningQuery {
			a.draw()
		}
		return
	}
	if isPrefix {
		a.pendingIsPrefix = true
		a.keyDisplay = disp
		a.keyDisplayExp = time.Time{}
		a.draw()
		return
	}
	// No match.
	a.pendingIsPrefix = false
	if tok.IsRune {
		a.pending = nil
		a.insertRune(tok.Rune)
		return
	}
	// Keep the sequence displayed briefly, then discard.
	a.setKeyDisplayTransient(disp)
	// pending is kept until expiry in the ticker; but to emulate the
	// joining of subsequent keys, leave a.pending as-is until expiry clears it.
	a.draw()
	// Schedule clearing by marking expiry; ticker clears keyDisplay and,
	// since pendingIsPrefix is false, also pending.
	go func() {}()
}

func (a *App) isSeqPrefix(seq string) bool {
	for k := range a.bindings {
		if len(k) > len(seq) && strings.HasPrefix(k, seq+"\x00") {
			return true
		}
	}
	return false
}

func (a *App) insertRune(r rune) {
	if unicode.IsControl(r) {
		return
	}
	a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
		nq := make([]rune, 0, len(q)+1)
		nq = append(nq, q[:caret]...)
		nq = append(nq, r)
		nq = append(nq, q[caret:]...)
		return nq, caret + 1
	})
}

// ---- query editing ----

func (a *App) actForwardChar() {
	if a.caret < len(a.queryRunes) {
		a.caret++
	}
}
func (a *App) actBackwardChar() {
	if a.caret > 0 {
		a.caret--
	}
}
func (a *App) actBeginningOfLine() { a.caret = 0 }
func (a *App) actEndOfLine()       { a.caret = len(a.queryRunes) }

func isWordSpace(r rune) bool {
	return unicode.IsSpace(r)
}

func forwardWordPos(q []rune, caret int) int {
	i := caret
	for i < len(q) && !isWordSpace(q[i]) {
		i++
	}
	for i < len(q) && isWordSpace(q[i]) {
		i++
	}
	return i
}
func backwardWordPos(q []rune, caret int) int {
	i := caret - 1
	for i >= 0 && isWordSpace(q[i]) {
		i--
	}
	for i >= 0 && !isWordSpace(q[i]) {
		i--
	}
	return i + 1
}

func (a *App) actForwardWord()  { a.caret = forwardWordPos(a.queryRunes, a.caret) }
func (a *App) actBackwardWord() { a.caret = backwardWordPos(a.queryRunes, a.caret) }

func (a *App) actDeleteForwardChar() {
	if a.caret < len(a.queryRunes) {
		a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
			nq := append([]rune{}, q[:caret]...)
			nq = append(nq, q[caret+1:]...)
			return nq, caret
		})
	}
}
func (a *App) actDeleteBackwardChar() {
	if a.caret > 0 {
		a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
			nq := append([]rune{}, q[:caret-1]...)
			nq = append(nq, q[caret:]...)
			return nq, caret - 1
		})
	}
}
func (a *App) actDeleteForwardWord() {
	a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
		if caret >= len(q) {
			return q, caret
		}
		i := caret
		if isWordSpace(q[i]) {
			for i < len(q) && isWordSpace(q[i]) {
				i++
			}
		} else {
			for i < len(q) && !isWordSpace(q[i]) {
				i++
			}
		}
		nq := append([]rune{}, q[:caret]...)
		nq = append(nq, q[i:]...)
		return nq, caret
	})
}
func (a *App) actDeleteBackwardWord() {
	a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
		if caret <= 0 {
			return q, caret
		}
		i := caret - 1
		if isWordSpace(q[i]) {
			for i >= 0 && isWordSpace(q[i]) {
				i--
			}
		} else {
			for i >= 0 && !isWordSpace(q[i]) {
				i--
			}
		}
		i++
		nq := append([]rune{}, q[:i]...)
		nq = append(nq, q[caret:]...)
		return nq, i
	})
}
func (a *App) actKillEndOfLine() {
	a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
		return append([]rune{}, q[:caret]...), caret
	})
}
func (a *App) actKillBeginningOfLine() {
	a.modifyQuery(func(q []rune, caret int) ([]rune, int) {
		return append([]rune{}, q[caret:]...), 0
	})
}
func (a *App) actDeleteAll() {
	a.caret = 0
	a.setQueryRunes(nil)
}
func (a *App) actEndOfFile() {
	if a.caret < len(a.queryRunes) {
		a.actDeleteForwardChar()
		return
	}
	if len(a.queryRunes) == 0 {
		a.actCancel()
	}
}

// ---- selection movement ----

func (a *App) bottomUp() bool { return a.layout == "bottom-up" }

// moveSelection moves by delta in visual direction. down=true means visual down.
func (a *App) moveVisual(down bool) {
	n := len(a.displayed)
	if n == 0 {
		return
	}
	old := a.selIndex
	delta := 1
	if !down {
		delta = -1
	}
	if a.bottomUp() {
		delta = -delta
	}
	ni := old + delta
	if ni < 0 {
		ni = n - 1
	}
	if ni >= n {
		ni = 0
	}
	a.selIndex = ni
	if a.rangeMode && old >= 0 && old < n {
		a.toggleSaved(a.displayed[old].Line)
	}
}

func (a *App) actSelectDown() { a.moveVisual(true) }
func (a *App) actSelectUp()   { a.moveVisual(false) }

func (a *App) pageVisual(down bool) {
	n := len(a.displayed)
	if n == 0 {
		return
	}
	g := a.geometry()
	per := g.perPage
	old := a.selIndex
	delta := per
	if !down {
		delta = -per
	}
	if a.bottomUp() {
		delta = -delta
	}
	ni := old + delta
	if delta > 0 && ni >= n {
		// If this is a range-mode page move, intermediate lines get
		// toggled; handle below.
		if a.rangeMode {
			a.toggleRangeBetween(old, n-1, 1)
		}
		a.selIndex = 0
		return
	}
	if delta < 0 && ni < 0 {
		if a.rangeMode {
			a.toggleRangeBetween(old, 0, -1)
		}
		a.selIndex = n - 1
		return
	}
	if a.rangeMode {
		step := 1
		if delta < 0 {
			step = -1
		}
		// toggle lines from old up to (not including) ni
		for i := old; i != ni; i += step {
			a.toggleSaved(a.displayed[i].Line)
		}
	}
	a.selIndex = ni
}

func (a *App) toggleRangeBetween(from, to, step int) {
	// toggle lines from `from` moving by step until passing `to` (from
	// included, to included except handled by caller semantics). This is
	// used only for wrap page moves; approximate by toggling from..to-1.
	n := len(a.displayed)
	for i := from; ; i += step {
		if i < 0 || i >= n {
			break
		}
		if i == to {
			break
		}
		a.toggleSaved(a.displayed[i].Line)
	}
}

func (a *App) actScrollPageDown() { a.pageVisual(true) }
func (a *App) actScrollPageUp()   { a.pageVisual(false) }

func (a *App) actScrollFirstItem() {
	if len(a.displayed) > 0 {
		a.selIndex = 0
	}
}
func (a *App) actScrollLastItem() {
	if len(a.displayed) > 0 {
		a.selIndex = len(a.displayed) - 1
	}
}
func (a *App) actScrollLeft() {
	w, _ := a.screen.Size()
	a.hscroll -= w / 2
	if a.hscroll < 0 {
		a.hscroll = 0
	}
}
func (a *App) actScrollRight() {
	w, _ := a.screen.Size()
	// maximum scroll is based on the longest displayed line on the page
	g := a.geometry()
	maxLen := 0
	for i := g.pageStart; i < len(a.displayed) && i < g.pageStart+g.perPage; i++ {
		lw := stringDisplayWidth(a.displayed[i].Line.Display)
		// account for tab expansion generously: tabs in original counted
		// via display expansion by print; approximate with rune count*? Use width.
		if lw > maxLen {
			maxLen = lw
		}
	}
	// The content area starts after prefixes; approximate available width by w.
	maxScroll := maxLen - w
	// If there is a selection prefix / jump label, content X reduces width.
	contentX := 0
	if a.selectionPrefix != "" {
		contentX += len(a.selectionPrefix) + 1
	}
	if a.jumpMode || a.cfg.SingleKeyJump.ShowPrefix {
		contentX += 2
	}
	maxScroll = maxLen - (w - contentX)
	if maxScroll < 0 {
		maxScroll = 0
	}
	a.hscroll += w / 2
	if a.hscroll > maxScroll {
		a.hscroll = maxScroll
	}
}

// ---- selection saving ----

func (a *App) toggleSaved(ln *Line) {
	if a.savedSel[ln] {
		delete(a.savedSel, ln)
	} else {
		a.savedSel[ln] = true
	}
}

func (a *App) currentLine() *Line {
	if a.selIndex >= 0 && a.selIndex < len(a.displayed) {
		return a.displayed[a.selIndex].Line
	}
	return nil
}

func (a *App) actToggleSelection() {
	if ln := a.currentLine(); ln != nil {
		a.toggleSaved(ln)
	}
}
func (a *App) actToggleSelectionAndSelectNext() {
	if ln := a.currentLine(); ln != nil {
		a.toggleSaved(ln)
	}
	a.moveVisual(true)
}
func (a *App) actSelectNone() {
	a.savedSel = map[*Line]bool{}
}
func (a *App) actSelectAll() {
	for _, r := range a.displayed {
		a.savedSel[r.Line] = true
	}
}
func (a *App) actSelectVisible() {
	g := a.geometry()
	for i := g.pageStart; i < len(a.displayed) && i < g.pageStart+g.perPage; i++ {
		a.savedSel[a.displayed[i].Line] = true
	}
}
func (a *App) actInvertSelection() {
	for _, r := range a.displayed {
		a.toggleSaved(r.Line)
	}
}
func (a *App) actGoToNextSelection() {
	n := len(a.displayed)
	for i := a.selIndex + 1; i < n; i++ {
		if a.savedSel[a.displayed[i].Line] {
			a.selIndex = i
			return
		}
	}
	for i := 0; i < n; i++ {
		if a.savedSel[a.displayed[i].Line] {
			a.selIndex = i
			return
		}
	}
}
func (a *App) actGoToPreviousSelection() {
	// Note the i > 0 bound mirrors the original's behaviour of never
	// landing on index 0 via the backward scan.
	for i := a.selIndex - 1; i > 0; i-- {
		if a.savedSel[a.displayed[i].Line] {
			a.selIndex = i
			return
		}
	}
	for i := len(a.displayed) - 1; i >= 0; i-- {
		if a.savedSel[a.displayed[i].Line] {
			a.selIndex = i
			return
		}
	}
}

// range mode
func (a *App) actToggleRangeMode() {
	if !a.rangeMode {
		a.rangeMode = true
		return
	}
	// turning off: toggle current line
	if ln := a.currentLine(); ln != nil {
		a.toggleSaved(ln)
	}
	a.rangeMode = false
}
func (a *App) actCancelRangeMode() {
	if a.rangeMode {
		if ln := a.currentLine(); ln != nil {
			a.toggleSaved(ln)
		}
		a.rangeMode = false
	}
}

// ---- filters / query ----

func (a *App) actRotateFilter() {
	a.filterIndex = (a.filterIndex + 1) % len(a.filters)
	a.requestQuery("filter")
}
func (a *App) actBackToInitialFilter() {
	a.filterIndex = 0
	a.requestQuery("filter")
}
func (a *App) actToggleQuery() {
	if len(a.queryRunes) > 0 {
		a.savedQuery = append([]rune{}, a.queryRunes...)
		a.caret = 0
		a.setQueryRunes(nil)
	} else {
		if a.savedQuery != nil {
			// setQueryRunes will request; caret at end
			r := append([]rune{}, a.savedQuery...)
			a.caret = len(r)
			a.setQueryRunes(r)
		}
	}
}
func (a *App) actRefreshScreen() {
	if a.screen != nil {
		a.screen.Sync()
	}
	a.requestQuery("refresh")
}

func (a *App) actToggleSingleKeyJump() {
	a.jumpMode = !a.jumpMode
}

// freeze / unfreeze
func (a *App) actFreezeResults() {
	if len(a.displayed) == 0 {
		a.statusMsg = "Nothing to freeze"
		a.keyDisplay = ""
		return
	}
	var lines []*Line
	for _, r := range a.displayed {
		lines = append(lines, r.Line)
	}
	a.frozen = lines
	a.isFrozen = true
	a.statusMsg = "Results frozen"
	a.keyDisplay = ""
	// clear query without going through setQueryRunes' status handling;
	// but non-sticky selection clearing on query change applies.
	old := a.queryString()
	a.queryRunes = nil
	a.caret = 0
	if old != "" && !a.cfg.StickySelection {
		a.savedSel = map[*Line]bool{}
	}
	a.requestQuery("force")
	a.statusMsg = "Results frozen"
	a.keyDisplay = ""
}
func (a *App) actUnfreezeResults() {
	if !a.isFrozen {
		a.statusMsg = "No frozen results"
		a.keyDisplay = ""
		return
	}
	a.isFrozen = false
	a.frozen = nil
	old := a.queryString()
	a.queryRunes = nil
	a.caret = 0
	if old != "" && !a.cfg.StickySelection {
		a.savedSel = map[*Line]bool{}
	}
	a.requestQuery("force")
	a.statusMsg = "Results unfrozen"
	a.keyDisplay = ""
}

// zoom
func (a *App) actZoomIn() {
	if a.zoomed {
		a.statusMsg = "Already zoomed in"
		a.keyDisplay = ""
		return
	}
	if len(a.queryRunes) == 0 || len(a.filtered) == 0 {
		a.statusMsg = "Nothing to zoom into"
		a.keyDisplay = ""
		return
	}
	raw := a.rawSnapshot()
	// map Line -> raw index
	rawIndex := map[*Line]int{}
	for i, ln := range raw {
		rawIndex[ln] = i
	}
	matchedSet := map[*Line]*Result{}
	include := map[int]bool{}
	for _, r := range a.filtered {
		matchedSet[r.Line] = r
		if ri, ok := rawIndex[r.Line]; ok {
			for d := -3; d <= 3; d++ {
				if ri+d >= 0 && ri+d < len(raw) {
					include[ri+d] = true
				}
			}
		}
	}
	var expanded []*Result
	for i, ln := range raw {
		if !include[i] {
			continue
		}
		if mr, ok := matchedSet[ln]; ok {
			expanded = append(expanded, &Result{Line: ln, Matched: mr.Matched, Context: false, zoomMatched: true})
		} else {
			expanded = append(expanded, &Result{Line: ln, Context: true})
		}
	}
	a.zoomOriginal = a.displayed
	a.zoomSelIndex = a.selIndex
	a.zoomed = true
	// move selection to same line if present
	curLine := a.currentLine()
	a.displayed = expanded
	if curLine != nil {
		for i, r := range expanded {
			if r.Line == curLine {
				a.selIndex = i
				break
			}
		}
	}
	a.clampSelection()
}
func (a *App) actZoomOut() {
	if !a.zoomed {
		a.statusMsg = "Not zoomed in"
		a.keyDisplay = ""
		return
	}
	a.zoomed = false
	a.displayed = a.zoomOriginal
	a.selIndex = a.zoomSelIndex
	a.clampSelection()
}

func (a *App) actViewAround() {
	curLine := a.currentLine()
	// clear query (directly; also clears ToggleQuery saved query state)
	a.savedQuery = nil
	old := a.queryString()
	a.queryRunes = nil
	a.caret = 0
	if old != "" && !a.cfg.StickySelection {
		a.savedSel = map[*Line]bool{}
	}
	// Determine position of curLine in the unfiltered source. If the
	// current display is an inconsistent snapshot (e.g. after ZoomOut with
	// an empty query), ViewAround does nothing further: we detect that by
	// checking whether the old query was empty and a zoom snapshot was
	// just restored. Simpler approximation from observation: if old query
	// is empty, ViewAround is a no-op.
	if old == "" {
		a.draw()
		return
	}
	source := a.sourceLines()
	results := a.currentFilter().Apply(source, "")
	a.filtered = results
	a.displayed = results
	a.lastQuery = ""
	a.lastFilter = a.currentFilter()
	a.hasExecuted = true
	if curLine != nil {
		for i, r := range results {
			if r.Line == curLine {
				a.selIndex = i
				break
			}
		}
	}
	a.clampSelection()
	// Note: zoomed flag is intentionally left untouched.
}

// finish / cancel
func (a *App) actFinish() {
	a.doFinish()
}
func (a *App) actCancel() {
	if a.rangeMode {
		a.actCancelRangeMode()
		return
	}
	a.doCancel()
}
