{"command":"cat > /tmp/replace_keybottom.py << 'PY'
s=open("keymap.go").read()
start=s.index("// convertKeyString")
end=s.index("// ---- tcell event -> KeyToken ----")
new=r'''func withMods(display string, id string, modC, modS, modM bool) (string, string) {
	dprefix := ""
	iprefix := ""
	if modC {
		dprefix += "C-"
		iprefix += "C-"
	}
	if modS {
		dprefix += "S-"
		iprefix += "S-"
	}
	if modM {
		dprefix = "M-" + dprefix
		iprefix = "M-" + iprefix
	}
	return dprefix + display, iprefix + id
}

// convertKeyString converts one comma-separated element of a keymap key
// into a KeyToken.
func convertKeyString(s string) (KeyToken, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
	}
	rest := s
	var modC, modM, modS bool
	peeledAny := true
	for peeledAny {
		peeledAny = false
		if strings.HasPrefix(rest, "C-") {
			modC = true
			rest = rest[2:]
			peeledAny = true
		} else if strings.HasPrefix(rest, "M-") {
			modM = true
			rest = rest[2:]
			peeledAny = true
		} else if strings.HasPrefix(rest, "S-") {
			modS = true
			rest = rest[2:]
			peeledAny = true
		}
	}
	if rest == "" {
		return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
	}
	if ent, ok := specialKeyNames[rest]; ok {
		display, id := ent[0], ent[1]
		if id == "Space" {
			if modC && !modM && !modS {
				return KeyToken{Name: "C-Space", ID: "C-Space"}, nil
			}
			if modM && !modC && !modS {
				return KeyToken{Name: "M-Space", ID: "M-Space", Rune: ' ', IsRune: true}, nil
			}
			if !modC && !modM && !modS {
				return KeyToken{Name: " ", ID: "Rune: ", Rune: ' ', IsRune: true}, nil
			}
			dn, idn := withMods("Space", "Space", modC, modS, modM)
			return KeyToken{Name: dn, ID: idn}, nil
		}
		dn, idn := withMods(display, id, modC, modS, modM)
		return KeyToken{Name: dn, ID: idn}, nil
	}
	// Legacy paths.
	if strings.HasPrefix(s, "M-") {
		inner := s[2:]
		if inner == "" {
			return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
		}
		if strings.HasPrefix(inner, "C-") {
			rest2 := inner[2:]
			if rest2 == "" {
				return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
			}
			ct, err := ctrlKeyToken(rest2)
			if err != nil {
				return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
			}
			ct.Name = "M-" + ct.Name
			ct.ID = "M-" + ct.ID
			return ct, nil
		}
		r := []rune(inner)[0]
		return KeyToken{Name: "M-" + string(r), ID: "M-Rune:" + string(r), Rune: r, IsRune: true}, nil
	}
	if strings.HasPrefix(s, "C-") {
		rest2 := s[2:]
		if rest2 == "" {
			return KeyToken{}, fmt.Errorf("failed to convert '%s': no such key", s)
		}
		return ctrlKeyToken(rest2)
	}
	if strings.HasPrefix(s, "S-") {
		return KeyToken{Name: "S", ID: "Rune:S", Rune: 'S', IsRune: true}, nil
	}
	r := []rune(s)[0]
	return KeyToken{Name: string(r), ID: "Rune:" + string(r), Rune: r, IsRune: true}, nil
}

func ctrlKeyToken(rest string) (KeyToken, error) {
	if ent, ok := specialKeyNames[rest]; ok {
		if ent[1] == "Space" {
			return KeyToken{Name: "C-Space", ID: "C-Space"}, nil
		}
		return KeyToken{Name: "C-" + ent[0], ID: "C-" + ent[1]}, nil
	}
	r := []rune(rest)[0]
	switch {
	case r >= 'a' && r <= 'z':
		return KeyToken{Name: "C-" + string(r), ID: "C-" + string(r)}, nil
	case r == '8':
		return KeyToken{Name: "C-8", ID: "C-8"}, nil
	case r == '2':
		return KeyToken{Name: "C-Space", ID: "C-Space"}, nil
	case r == '[':
		return KeyToken{Name: "Esc", ID: "Esc"}, nil
	default:
		return KeyToken{Name: "C-" + string(r), ID: "C-" + string(r)}, nil
	}
}

// parseKeySequence parses a comma-separated key sequence string.
func parseKeySequence(s string) ([]KeyToken, error) {
	parts := strings.Split(s, ",")
	var toks []KeyToken
	for _, p := range parts {
		tok, err := convertKeyString(p)
		if err != nil {
			return nil, fmt.Errorf("unknown key %s: %w", s, err)
		}
		toks = append(toks, tok)
	}
	return toks, nil
}

func seqKey(toks []KeyToken) string {
	ids := make([]string, len(toks))
	for i, t := range toks {
		id := t.ID
		if id == "" {
			id = t.Name
		}
