		col  int
	}
	var stack []bracket
	inSingle := false
	inDouble := false
	quoteLine, quoteCol := 0, 0
	var quoteChar rune
	for li, line := range lines {
		runes := []rune(line)
		prevNonSpace := rune(0)
		for i := 0; i < len(runes); i++ {
			r := runes[i]
			col := i + 1
			if inSingle {
				if r == '\'' {
					if i+1 < len(runes) && runes[i+1] == '\'' {
						i++
						continue
					}
					inSingle = false
				}
				continue
			}
			if inDouble {
				if r == '\\' {
					i++
					continue
				}
				if r == '"' {
					inDouble = false
				}
				continue
			}
			if r == '#' && (i == 0 || runes[i-1] == ' ' || runes[i-1] == '\t') {
				break
			}
			tokenStart := i == 0 || prevNonSpace == 0 || prevNonSpace == ':' || prevNonSpace == ',' || prevNonSpace == '[' || prevNonSpace == '{' || prevNonSpace == '-'
			if (r == '\'' || r == '"') && tokenStart {
				if r == '\'' {
					inSingle = true
				} else {
					inDouble = true
				}
				quoteChar = r
				quoteLine = li + 1
				quoteCol = col
				prevNonSpace = r
				continue
			}
			if (r == '[' || r == '{') && tokenStart {
				stack = append(stack, bracket{ch: r, line: li + 1, col: col})
			} else if r == ']' || r == '}' {
				if len(stack) > 0 {
					top := stack[len(stack)-1]
					if (top.ch == '[' && r == ']') || (top.ch == '{' && r == '}') {
						stack = stack[:len(stack)-1]
					}
				}
			}
			if r != ' ' && r != '\t' {
				prevNonSpace = r
			}
		}
		// goccy does not continue a quoted scalar past end of line in
		// these cases (v3 has already failed).
		if inSingle || inDouble {
			kind := "double-quoted"
			if quoteChar == '\'' {
				kind = "single-quoted"
			}
			return yamlAnnotate(data, quoteLine, quoteCol, "could not find end character of "+kind+" text")
		}
	}
	if len(stack) > 0 {
		// report the most recent unclosed bracket
		b := stack[len(stack)-1]
		if b.ch == '[' {
			return yamlAnnotate(data, b.line, b.col, "sequence end token ']' not found")
		}
		return yamlAnnotate(data, b.line, b.col, "could not find flow mapping end token '}'")
	}
	return nil
}

func yamlAnnotateRaw(data []byte, line, col int, msg string) error {
	lines := strings.Split(string(data), "\n")
	var b strings.Builder
	fmt.Fprintf(&b, "failed to decode YAML: [%d:%d] %s\n", line, col, msg)
	start := line - 2
	if start < 1 {
		start = 1
	}
	for ln := start; ln <= line && ln <= len(lines); ln++ {
		prefix := "   "
		if ln == line {
			prefix = ">  "
		}
		fmt.Fprintf(&b, "%s%d | %s\n", prefix, ln, lines[ln-1])
		if ln == line {
			fmt.Fprintf(&b, "%s^\n", strings.Repeat(" ", col+len(strconv.Itoa(ln))+5))
		}
	}
	s := b.String()
	s = strings.TrimSuffix(s, "\n")
	return &yamlDecodeError{msg: s}
}

func findMissingAlias(data []byte, n *yaml.Node) error {
	if n == nil {
		return nil
	}
	if n.Kind == yaml.AliasNode && n.Alias == nil {
		return yamlAnnotate(data, n.Line, n.Column, fmt.Sprintf("could not find alias %q", n.Value))
	}
	for _, c := range n.Content {
		if err := findMissingAlias(data, c); err != nil {
			return err
		}
	}
	return nil
}
