	if _, ok := builtinActions[name]; ok {
		return []string{name}, nil
	}
	if seen[name] {
		return nil, fmt.Errorf("could not resolve %s: deep recursion", name)
	}
	if subs, ok := custom[name]; ok {
		seen[name] = true
		defer delete(seen, name)
		var out []string
		for _, sub := range subs {
			resolved, err := resolveActionSeen(sub, custom, seen)
			if err != nil {
				return nil, err
			}
			out = append(out, resolved...)
		}
		return out, nil
	}
	return nil, fmt.Errorf("could not resolve %s: no such action", name)
}

'''
