s=open("configload.go").read()
# Replace root walk
old="""	// Walk pairs
	for i := 0; i+1 < len(root.Content); i += 2 {
		keyNode := root.Content[i]
		valNode := root.Content[i+1]
		key := keyNode.Value
		if err := yamlApplyField(data, cfg, key, valNode); err != nil {
			return err
		}
	}
	return nil"""
new="""	pairs, err := mappingPairs(data, root, "Config")
	if err != nil {
		return err
	}
	for _, p := range pairs {
		if err := yamlApplyField(data, cfg, p[0].Value, p[1]); err != nil {
			return err
		}
	}
	return nil"""
assert old in s; s=s.replace(old,new)
# Duplicate check: skip '<<' keys
s=s.replace("""		for i := 0; i+1 < len(n.Content); i += 2 {
			k := n.Content[i]
			if prev, ok := seen[k.Value]; ok {""","""		for i := 0; i+1 < len(n.Content); i += 2 {
			k := n.Content[i]
			if k.Value == "<<" {
				if err := yamlCheckDuplicates(data, n.Content[i+1]); err != nil {
					return err
				}
				continue
			}
			if prev, ok := seen[k.Value]; ok {""")
# Replace mappingPairs with merging version
start=s.index("func mappingPairs(")
end=s.index("func yamlApplyField",start)
newfn=r'''func flattenMapping(data []byte, n *yaml.Node) ([][2]*yaml.Node, error) {
	n = derefAlias(n)
	if nodeIsNull(n) {
		return nil, nil
	}
	if n.Kind != yaml.MappingNode {
		return nil, yamlTypeError(data, n, fmt.Sprintf("%s was used where mapping is expected", yamlKindName(n)))
	}
	explicit := map[string]bool{}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value != "<<" {
			explicit[n.Content[i].Value] = true
		}
	}
	var pairs [][2]*yaml.Node
	seen := map[string]bool{}
	for i := 0; i+1 < len(n.Content); i += 2 {
		k := n.Content[i]
		v := n.Content[i+1]
		if k.Value == "<<" {
			mv := derefAlias(v)
			var mergedNodes []*yaml.Node
			if mv.Kind == yaml.SequenceNode {
				mergedNodes = mv.Content
			} else {
				mergedNodes = []*yaml.Node{mv}
			}
			for _, mn := range mergedNodes {
				sub, err := flattenMapping(data, mn)
				if err != nil {
					return nil, err
				}
				for _, sp := range sub {
					key := sp[0].Value
					if explicit[key] || seen[key] {
						continue
					}
					seen[key] = true
					pairs = append(pairs, sp)
				}
			}
			continue
		}
		if seen[k.Value] {
			continue
		}
		seen[k.Value] = true
		pairs = append(pairs, [2]*yaml.Node{k, v})
	}
	return pairs, nil
}

func mappingPairs(data []byte, n *yaml.Node, fieldPath string) ([][2]*yaml.Node, error) {
	return flattenMapping(data, n)
}

'''
